// 11개월차 (Day 301~330) · ep 54,55,56,57,58,59
window.JJ_DAYS = Object.assign(window.JJ_DAYS || {}, {"302":{"day":302,"ep":"54","epTitle":"東京第1結界①","epTitleKo":"도쿄 제1결계 1","title":"〜てからでないと — ~하고 나서가 아니면","watch":"54화 중반부 · 식신 코가네가 사멸회유의 점수 규칙을 알려 주는 장면","scene":"결계에 들어가면 참가자마다 '코가네'라는 식신이 붙어 규칙과 점수를 알려 준다. 다른 참가자를 쓰러뜨리면 점수를 얻고, 100점을 모아야 새 규칙을 추가할 수 있다. 이타도리는 무작정 싸우기 전에 규칙부터 확인한다.","lines":[{"who":"코가네","ja":"百点を集めてからでないと、規則は追加できないよ！","kana":"ひゃくてんを あつめて からで ないと、きそくは ついか できないよ！","ko":"100점을 모으고 나서가 아니면 규칙은 추가할 수 없어!"},{"who":"이타도리","ja":"情報を確認してからでないと、うかつに動けないな。","kana":"じょうほうを かくにん して からで ないと、うかつに うごけないな。","ko":"정보를 확인하고 나서가 아니면 섣불리 못 움직이겠네."},{"who":"이타도리","ja":"点数の条件を聞いてからでないと、判断できない。","kana":"てんすうの じょうけんを きいて からで ないと、はんだん できない。","ko":"점수 조건을 듣고 나서가 아니면 판단할 수 없어."}],"words":[{"w":"加算","r":"かさん","ko":"가산, 더함"},{"w":"獲得","r":"かくとく","ko":"획득"},{"w":"不備","r":"ふび","ko":"미비, 빠진 것"},{"w":"受理","r":"じゅり","ko":"수리, 접수"},{"w":"差し戻し","r":"さしもどし","ko":"반려, 되돌려 보냄"},{"w":"交付","r":"こうふ","ko":"교부, 발급"},{"w":"照会","r":"しょうかい","ko":"조회"},{"w":"押印","r":"おういん","ko":"날인, 도장 찍기"}],"grammar":{"point":"〜てからでないと","desc":"〜てからでないと는 '~하고 나서가 아니면 (~할 수 없다)'라는 뜻입니다. 동사 て형 + からでないと 뒤에 できない・無理だ 같은 부정 표현이 옵니다. '먼저 A가 꼭 필요하다'는 조건을 강조합니다. 더 딱딱하게는 〜てからでなければ라고 합니다. 업무에서 '확인 후가 아니면 답변드릴 수 없습니다'처럼 정중하게 선을 그을 때 좋습니다.","ex":[{"ja":"上司に相談してからでないと、お返事できません。","kana":"じょうしに そうだん して からで ないと、おへんじ できません。","ko":"상사와 의논하고 나서가 아니면 답변드릴 수 없습니다."},{"ja":"内容を確認してからでないと、契約はおすすめできません。","kana":"ないようを かくにん して からで ないと、けいやくは おすすめ できません。","ko":"내용을 확인하고 나서가 아니면 계약은 권해 드릴 수 없습니다."}]},"convert":{"anime":"金払ってからじゃねーと入れねーぞ。","real":"お支払いいただいてからでないと、ご入場いただけません。","note":"じゃねーと(でないと)와 入れねー(入れない)는 거친 축약입니다. 손님에게는 お支払いいただいて와 ご入場いただけません으로 정중하게 조건을 알립니다."},"mission":"고객이 '오늘 바로 가입하고 싶다'고 할 때, 먼저 필요한 절차를 〜てからでないと로 설명해 보세요.","missionEx":{"ja":"健康状態を確認してからでないと、お申し込みはできません。","kana":"けんこう じょうたいを かくにん して からで ないと、おもうしこみは できません。","ko":"건강 상태를 확인하고 나서가 아니면 신청은 할 수 없습니다."},"quiz":[{"q":"「의논하고 나서가 아니면 정할 수 없다」를 일본어로?","choices":["相談してからでないと、決められない。","相談しないうちに、決められない。","相談してはじめて、決められない。"],"a":0,"why":"'A하고 나서가 아니면 B할 수 없다'는 〜てからでないと〜ない입니다."},{"q":"올바른 형태는?","choices":["確認するからでないと","確認してからでないと","確認したからでないと"],"a":1,"why":"동사 て형 + からでないと입니다."},{"q":"「受理」의 뜻은?","choices":["승인","신청","수리, 접수"],"a":2,"why":"受理(じゅり)는 서류를 받아들이는 것, 접수입니다. 申請(신청) → 受理(접수) → 承認(승인)."}]},"303":{"day":303,"ep":"54","epTitle":"東京第1結界①","epTitleKo":"도쿄 제1결계 1","title":"〜てはじめて — ~하고 나서야 비로소","watch":"54화 중반부 · 이타도리가 결계 안의 다른 참가자와 처음 맞닥뜨리는 장면","scene":"결계 안은 생각보다 훨씬 거칠다. 이타도리는 다른 참가자의 공격을 받으며 이 게임이 얼마나 위험한지 몸소 깨닫는다. 갑자기 휘말린 참가자들의 처지도 직접 보고 나서야 이해하게 된다.","lines":[{"who":"이타도리","ja":"実際に入ってはじめて、ここの怖さが分かった。","kana":"じっさいに はいって はじめて、ここの こわさが わかった。","ko":"실제로 들어와 보고 나서야 이곳의 무서움을 알았어."},{"who":"이타도리","ja":"敵と戦ってはじめて、相手の立場に気づいた。","kana":"てきと たたかって はじめて、あいての たちばに きづいた。","ko":"적과 싸워 보고 나서야 상대의 입장을 깨달았어."},{"who":"후시구로","ja":"一人になってはじめて、仲間の価値が分かるな。","kana":"ひとりに なって はじめて、なかまの かちが わかるな。","ko":"혼자가 되고 나서야 비로소 동료의 소중함을 알겠네."}],"words":[{"w":"実際","r":"じっさい","ko":"실제"},{"w":"実感","r":"じっかん","ko":"실감"},{"w":"痛感","r":"つうかん","ko":"통감, 뼈저리게 느낌"},{"w":"大変","r":"たいへん","ko":"힘듦, 큰일"},{"w":"身にしみる","r":"みにしみる","ko":"뼈저리게 느끼다"},{"w":"弱者","r":"じゃくしゃ","ko":"약자"},{"w":"境遇","r":"きょうぐう","ko":"처지, 환경"},{"w":"理不尽","r":"りふじん","ko":"불합리함, 부당함"}],"grammar":{"point":"〜てはじめて","desc":"〜てはじめて는 '~하고 나서야 비로소'라는 뜻입니다. 동사 て형 + はじめて 형태로, 그 전에는 몰랐던 것을 경험한 뒤에야 깨달았다는 느낌을 줍니다. 뒤에는 分かる・気づく・知る 같은 '깨닫다' 계열 동사가 자주 옵니다. 한국어 '~해 보고서야 비로소'와 거의 같습니다.","ex":[{"ja":"親になってはじめて、親の大変さが分かりました。","kana":"おやに なって はじめて、おやの たいへんさが わかりました。","ko":"부모가 되고 나서야 비로소 부모의 고생을 알았습니다."},{"ja":"実際にお客様と話してはじめて、保険の意味に気づきました。","kana":"じっさいに おきゃくさまと はなして はじめて、ほけんの いみに きづきました。","ko":"실제로 고객님과 이야기해 보고 나서야 보험의 의미를 깨달았습니다."}]},"convert":{"anime":"やってみて初めてわかったわ、マジきちぃ。","real":"実際にやってみてはじめて、大変さが分かりました。","note":"きちぃ는 きつい(힘들다)의 거친 발음이고 マジ는 속어입니다. 업무 보고에서는 大変さが分かりました로 차분하게 말합니다."},"mission":"어떤 경험을 하고 나서야 알게 된 것을 〜てはじめて로 말해 보세요. (예: 아이가 태어나고, 이 일을 하고)","missionEx":{"ja":"子どもが生まれてはじめて、保険の価値が分かりました。","kana":"こどもが うまれて はじめて、ほけんの かちが わかりました。","ko":"아이가 태어나고 나서야 비로소 보험의 가치를 알았습니다."},"quiz":[{"q":"「아이가 생기고 나서야 알았다」로 맞는 것은?","choices":["子どもができないうちに分かった。","子どもができてはじめて分かった。","子どもができるはじめて分かった。"],"a":1,"why":"동사 て형 + はじめて가 '~하고 나서야 비로소'입니다."},{"q":"〜てはじめて 뒤에 자주 오는 동사는?","choices":["分かる・気づく","食べる・飲む","行く・来る"],"a":0,"why":"경험 뒤의 '깨달음'을 말하므로 分かる・気づく가 잘 어울립니다."},{"q":"「境遇」의 뜻은?","choices":["실감","처지, 환경","약자"],"a":1,"why":"境遇(きょうぐう)는 놓인 처지·환경입니다."}]},"304":{"day":304,"ep":"54","epTitle":"東京第1結界①","epTitleKo":"도쿄 제1결계 1","title":"〜以上(は) — ~한 이상(은)","watch":"54화 후반부 · 따로 떨어진 후시구로가 싸움을 각오하는 장면","scene":"다른 곳에 떨어진 후시구로도 참가자들의 표적이 된다. 그는 누나를 구하려고 스스로 이 게임을 택한 이상 끝까지 물러서지 않겠다고 다짐한다. 이타도리 역시 맡은 일을 끝까지 해내겠다고 마음먹는다.","lines":[{"who":"후시구로","ja":"自分で選んだ以上、最後までやるしかない。","kana":"じぶんで えらんだ いじょう、さいごまで やるしか ない。","ko":"스스로 선택한 이상 끝까지 할 수밖에 없어."},{"who":"이타도리","ja":"引き受けた以上は、途中で投げ出さねえよ。","kana":"ひきうけた いじょうは、とちゅうで なげださねえよ。","ko":"맡은 이상은 도중에 내팽개치지 않아."},{"who":"후시구로","ja":"結界に入った以上、もう後戻りはできない。","kana":"けっかいに はいった いじょう、もう あともどりは できない。","ko":"결계에 들어온 이상 이제 되돌아갈 수는 없어."}],"words":[{"w":"責務","r":"せきむ","ko":"책무"},{"w":"全うする","r":"まっとうする","ko":"완수하다, 끝까지 해내다"},{"w":"撤退","r":"てったい","ko":"철수, 물러남"},{"w":"決断","r":"けつだん","ko":"결단"},{"w":"貫く","r":"つらぬく","ko":"관철하다"},{"w":"委任","r":"いにん","ko":"위임"},{"w":"果たす","r":"はたす","ko":"다하다, 완수하다"},{"w":"投げ出す","r":"なげだす","ko":"내팽개치다, 포기하다"}],"grammar":{"point":"〜以上(は)","desc":"〜以上(は)는 '~한 이상(은) 당연히 ~해야 한다'라는 뜻으로 책임이나 각오를 말할 때 씁니다. 동사 보통형(주로 た형) + 以上(は) 형태입니다. 뒤에는 〜なければならない・〜しかない・〜べきだ・〜つもりだ 같은 의무·결심 표현이 자주 옵니다. 비슷한 말로 〜からには가 있습니다.","ex":[{"ja":"契約を引き受けた以上は、最後まで責任を持ちます。","kana":"けいやくを ひきうけた いじょうは、さいごまで せきにんを もちます。","ko":"계약을 맡은 이상은 끝까지 책임지겠습니다."},{"ja":"目標を決めた以上、毎月の結果を確認しましょう。","kana":"もくひょうを きめた いじょう、まいつきの けっかを かくにん しましょう。","ko":"목표를 정한 이상 매달 결과를 확인합시다."}]},"convert":{"anime":"やるって言った以上、逃げんなよ。","real":"お約束した以上、責任を持って対応いたします。","note":"逃げんな는 逃げるな의 거친 축약 명령입니다. 고객에게는 같은 以上를 쓰되 '제가 책임지겠다'는 정중한 약속으로 바꿉니다."},"mission":"새 고객을 담당하게 되었습니다. 〜以上로 끝까지 책임지겠다고 말해 보세요.","missionEx":{"ja":"担当になった以上、最後までお任せください。","kana":"たんとうに なった いじょう、さいごまで おまかせ ください。","ko":"담당이 된 이상 끝까지 맡겨 주십시오."},"quiz":[{"q":"「맡은 이상 끝까지 하겠습니다」를 일본어로?","choices":["引き受けたので最後までします。","引き受けるより最後までします。","引き受けた以上、最後までやります。"],"a":2,"why":"책임·각오를 말할 때는 〜た以上를 씁니다."},{"q":"〜以上は 뒤에 자연스러운 표현은?","choices":["〜しかない / 〜なければならない","〜かもしれない","〜たことがある"],"a":0,"why":"〜以上は 뒤에는 의무·결심 표현이 옵니다."},{"q":"「撤退」의 뜻은?","choices":["책무","철수, 물러남","결단"],"a":1,"why":"撤退(てったい)는 물러나는 것, 철수입니다."}]},"305":{"day":305,"ep":"54","epTitle":"東京第1結界①","epTitleKo":"도쿄 제1결계 1","title":"응용 회화 — 54화 총정리","watch":"54화 클라이맥스 · 흩어진 이타도리와 후시구로가 다시 만나기 위해 움직이는 장면","scene":"흩어진 이타도리와 후시구로는 각자 위기를 넘기며 서로를 찾는다. 규칙과 점수의 구조를 알게 된 두 사람은 목적을 이루려면 다른 참가자들과의 만남을 피할 수 없다는 것을 깨닫는다. 도쿄 제1결계에서의 본격적인 싸움이 시작된다.","lines":[{"who":"이타도리","ja":"日が暮れないうちに、伏黒を見つけなきゃ。","kana":"ひが くれない うちに、ふしぐろを みつけなきゃ。","ko":"해가 지기 전에 후시구로를 찾아야 해."},{"who":"후시구로","ja":"位置を確かめてからでないと、合図は出せない。","kana":"いちを たしかめて からで ないと、あいずは だせない。","ko":"위치를 확인하고 나서가 아니면 신호는 보낼 수 없어."},{"who":"이타도리","ja":"ここに来た以上は、必ず二人で生き残ろう。","kana":"ここに きた いじょうは、かならず ふたりで いきのころう。","ko":"여기 온 이상은 반드시 둘이서 살아남자."}],"words":[{"w":"一安心","r":"ひとあんしん","ko":"일단 안심"},{"w":"狼煙","r":"のろし","ko":"봉화, 신호 연기"},{"w":"居場所","r":"いばしょ","ko":"있는 곳, 거처"},{"w":"無傷","r":"むきず","ko":"상처 없음, 무사함"},{"w":"散り散り","r":"ちりぢり","ko":"뿔뿔이"},{"w":"落ち合う","r":"おちあう","ko":"(약속한 곳에서) 만나다"},{"w":"生き残る","r":"いきのこる","ko":"살아남다"},{"w":"胸をなで下ろす","r":"むねをなでおろす","ko":"가슴을 쓸어내리다"}],"grammar":{"point":"응용 회화 — 54화 총정리","desc":"〜ないうちに: ~하기 전에 (그렇게 되면 곤란하니 늦기 전에)\n〜てからでないと: ~하고 나서가 아니면 (~할 수 없다)\n〜てはじめて: ~하고 나서야 비로소 (깨달음)\n〜以上(は): ~한 이상(은) 당연히 (책임·각오)","ex":[{"ja":"お客様と直接お会いしてはじめて、本当のご希望が分かりました。","kana":"おきゃくさまと ちょくせつ おあいして はじめて、ほんとうの ごきぼうが わかりました。","ko":"고객님을 직접 뵙고 나서야 비로소 진짜 바라시는 것을 알았습니다."},{"ja":"お引き受けした以上、手続きが無事に終わるまで担当いたします。","kana":"おひきうけ した いじょう、てつづきが ぶじに おわる まで たんとう いたします。","ko":"맡은 이상, 절차가 무사히 끝날 때까지 담당하겠습니다."}]},"convert":{"anime":"ぐずぐずしてっと置いてくぞ。","real":"お時間が過ぎないうちに、ご移動をお願いいたします。","note":"してっと(していると)와 置いてく(置いていく)는 반말 축약이고 협박조로 들립니다. 고객에게는 〜ないうちに로 부드럽게 서둘러 달라고 부탁합니다."},"mission":"롤플레이: 일본인 고객이 「今日すぐ契約できますか？」라고 묻습니다. ① 〜てからでないと로 먼저 필요한 절차를 말하고 ② 〜以上로 끝까지 돕겠다고 답해 보세요.","missionEx":{"ja":"内容をご確認いただいてからでないと契約できませんが、お引き受けした以上、必ずサポートいたします。","kana":"ないようを ごかくにん いただいて からで ないと けいやく できませんが、おひきうけ した いじょう、かならず さぽーと いたします。","ko":"내용을 확인하신 뒤가 아니면 계약할 수 없지만, 맡은 이상 반드시 도와드리겠습니다."},"quiz":[{"q":"「해가 지기 전에 합류하자」로 맞는 것은?","choices":["日が暮れるうちに合流しよう。","日が暮れないうちに合流しよう。","日が暮れてはじめて合流しよう。"],"a":1,"why":"'늦기 전에'는 ない형 + うちに입니다."},{"q":"「여기 온 이상은 반드시 살아남자」로 맞는 것은?","choices":["来た以上は、必ず生き残ろう。","来たどころか、必ず生き残ろう。","来てからでないと、必ず生き残ろう。"],"a":0,"why":"각오를 말할 때는 〜た以上は입니다."},{"q":"「狼煙」의 뜻은?","choices":["있는 곳","봉화, 신호 연기","든든함"],"a":1,"why":"狼煙(のろし)는 신호로 올리는 연기, 봉화입니다. 狼煙を上げる = 신호탄을 쏘다."}]},"306":{"day":306,"ep":"55","epTitle":"東京第1結界②","epTitleKo":"도쿄 제1결계 2","title":"〜たところ — ~했더니 (결과)","watch":"55화 전반부 · 결계 안에서 소문을 쫓는 이타도리","scene":"도쿄 제1결계에 들어간 이타도리는 룰을 추가할 점수를 모으기 위해 정보를 모은다. 그러다 점수를 아주 많이 가진 플레이어가 있다는 소문을 듣고, 그 사람이 전직 변호사 히구루마 히로미라는 것을 알게 된다.","lines":[{"who":"이타도리","ja":"噂を調べてみたところ、元弁護士の人がいるらしい。","kana":"うわさを しらべて みた ところ、もと べんごしの ひとが いる らしい。","ko":"소문을 조사해 봤더니 전직 변호사인 사람이 있다나 봐."},{"who":"이타도리","ja":"点数を確認したところ、かなり多く持ってるみたいだ。","kana":"てんすうを かくにん した ところ、かなり おおく もってる みたいだ。","ko":"점수를 확인했더니 꽤 많이 갖고 있는 것 같아."},{"who":"히구루마","ja":"君か。ちょうど一つ、裁判が終わったところだ。","kana":"きみか。ちょうど ひとつ、さいばんが おわった ところだ。","ko":"너로군. 마침 재판 하나가 막 끝난 참이다."}],"words":[{"w":"評判","r":"ひょうばん","ko":"평판"},{"w":"弁護士","r":"べんごし","ko":"변호사"},{"w":"聞き込み","r":"ききこみ","ko":"탐문"},{"w":"裏付け","r":"うらづけ","ko":"뒷받침, 입증"},{"w":"突き止める","r":"つきとめる","ko":"밝혀내다"},{"w":"手がかり","r":"てがかり","ko":"단서"},{"w":"実態","r":"じったい","ko":"실태"},{"w":"尋ねる","r":"たずねる","ko":"묻다, 질문하다"}],"grammar":{"point":"〜たところ","desc":"동사 た형 + ところ는 'A했더니 (그 결과) B였다'라는 뜻입니다. 어떤 행동을 해 본 뒤 알게 된 결과를 보고할 때 쓰며, 한국어 '~했더니', '~해 보니'에 해당합니다. 뒤에는 이미 일어난 사실이 오고, 확인·조사 결과를 전하는 업무 보고에서 특히 자주 씁니다. 한편 '막 ~한 참이다'(今、終わったところです)라는 뜻도 있으니 문맥으로 구분하세요. 비즈니스에서는 '確認しましたところ'처럼 정중형으로도 씁니다.","ex":[{"ja":"先方に確認したところ、明日の会議は中止になりました。","kana":"せんぽうに かくにん した ところ、あしたの かいぎは ちゅうしに なりました。","ko":"상대 회사에 확인했더니 내일 회의는 취소되었습니다."},{"ja":"保険料を計算したところ、意外と安くなりました。","kana":"ほけんりょうを けいさん した ところ、いがいと やすく なりました。","ko":"보험료를 계산해 봤더니 의외로 저렴해졌습니다."}]},"convert":{"anime":"調べてみたら、マジでヤバい奴だった。","real":"お調べしたところ、注意が必要な方のようです。","note":"〜てみたら·マジ·ヤバい는 친구끼리 쓰는 구어입니다. 보고할 때는 〜たところ로 결과를 차분하게 전하고, 사람은 奴 대신 方(분)이라고 합니다."},"mission":"고객의 계약이나 서류를 확인해 본 결과를 〜たところ로 보고해 보세요.","missionEx":{"ja":"お客様の契約を調べたところ、来月が満期でした。","kana":"おきゃくさまの けいやくを しらべた ところ、らいげつが まんきでした。","ko":"고객님 계약을 확인해 보니 다음 달이 만기였습니다."},"quiz":[{"q":"「확인했더니 문제가 없었습니다」를 일본어로?","choices":["確認するところ、問題はありませんでした。","確認したところ、問題はありませんでした。","確認しているところ、問題はありませんでした。"],"a":1,"why":"결과를 말할 때는 동사 た형 + ところ입니다."},{"q":"「今、会議が終わったところです」의 뜻은?","choices":["지금 막 회의가 끝났습니다.","회의가 끝났더니 지금입니다.","지금 회의가 끝나려고 합니다."],"a":0,"why":"〜たところ에는 '막 ~한 참'이라는 뜻도 있습니다."},{"q":"「評判」의 읽기는?","choices":["ひょうばん","へいばん","ひょうはん"],"a":0,"why":"評判(ひょうばん)은 '평판, 소문'입니다."}]},"307":{"day":307,"ep":"55","epTitle":"東京第1結界②","epTitleKo":"도쿄 제1결계 2","title":"〜あげく — ~한 끝에 결국 (안 좋은 결과)","watch":"55화 중반부 · 히구루마의 변호사 시절 회상","scene":"히구루마의 과거가 그려진다. 그는 정의를 믿고 피고인을 변호해 온 변호사였지만, 오랜 재판 끝에 받아들이기 힘든 판결을 마주하며 제도에 깊이 실망한다. 그 절망 속에서 그는 술사의 힘에 눈을 뜬다.","lines":[{"who":"히구루마","ja":"何年も悩んだあげく、答えは見つからなかった。","kana":"なんねんも なやんだ あげく、こたえは みつからなかった。","ko":"몇 년이나 고민한 끝에 결국 답은 찾지 못했다."},{"who":"히구루마","ja":"長い議論のあげく、判決はひっくり返らなかった。","kana":"ながい ぎろんの あげく、はんけつは ひっくりかえらなかった。","ko":"긴 논쟁 끝에 결국 판결은 뒤집히지 않았다."},{"who":"이타도리","ja":"結局、あの人は正しいことを信じられなくなったのか。","kana":"けっきょく、あの ひとは ただしい ことを しんじられなく なったのか。","ko":"결국 그 사람은 옳은 것을 믿을 수 없게 된 건가."}],"words":[{"w":"悩む","r":"なやむ","ko":"고민하다"},{"w":"冤罪","r":"えんざい","ko":"누명, 억울한 죄"},{"w":"控訴","r":"こうそ","ko":"항소"},{"w":"議論","r":"ぎろん","ko":"논의, 논쟁"},{"w":"幻滅","r":"げんめつ","ko":"환멸"},{"w":"裁判","r":"さいばん","ko":"재판"},{"w":"判決","r":"はんけつ","ko":"판결"},{"w":"信用","r":"しんよう","ko":"신용, 믿음"}],"grammar":{"point":"〜あげく","desc":"동사 た형 + あげく(명사는 명사 + の + あげく)는 'A를 오랫동안 한 끝에 결국 B'라는 뜻입니다. 한국어 '~한 끝에 결국', '~하다 하다'에 가깝고, B에는 주로 실망스럽거나 곤란한 결과가 옵니다. A에는 さんざん·何度も·長い時間처럼 '오래, 많이'를 나타내는 말이 자주 함께 나옵니다. 좋은 결과에는 잘 쓰지 않는다는 점이 다음에 배울 〜末に와의 차이입니다.","ex":[{"ja":"さんざん迷ったあげく、何も買わずに帰りました。","kana":"さんざん まよった あげく、なにも かわずに かえりました。","ko":"한참 망설인 끝에 결국 아무것도 사지 않고 돌아왔습니다."},{"ja":"何度も説明したあげく、契約はキャンセルになりました。","kana":"なんども せつめい した あげく、けいやくは キャンセルに なりました。","ko":"몇 번이나 설명했는데 결국 계약은 취소되었습니다."}]},"convert":{"anime":"さんざん迷ったあげく、やめるってマジ？","real":"いろいろご検討いただいた結果、今回は見送られるということでしょうか。","note":"고객에게 あげく를 쓰면 '그렇게 끌더니 결국'이라는 불만이 드러납니다. 고객의 결정은 ご検討いただいた結果로 존중하며 확인하는 것이 예의입니다."},"mission":"오래 고민하거나 애썼는데 결과가 안 좋았던 경험을 〜あげく로 말해 보세요. (예: 영업, 여행 계획, 쇼핑)","missionEx":{"ja":"一時間も道に迷ったあげく、店は休みでした。","kana":"いちじかんも みちに まよった あげく、みせは やすみでした。","ko":"한 시간이나 길을 헤맨 끝에 결국 가게는 휴무였습니다."},"quiz":[{"q":"〜あげく 뒤에 주로 오는 결과는?","choices":["기쁘고 좋은 결과","실망스럽거나 곤란한 결과","미래의 계획"],"a":1,"why":"あげく는 오래 애쓴 끝의 부정적인 결과에 주로 씁니다."},{"q":"명사에 あげく를 붙인 올바른 형태는?","choices":["議論のあげく","議論なあげく","議論したのあげく"],"a":0,"why":"명사는 명사 + の + あげく입니다."},{"q":"「判決」의 뜻은?","choices":["재판","신용","판결"],"a":2,"why":"判決(はんけつ)은 '판결'입니다. 재판은 裁判(さいばん)."}]},"309":{"day":309,"ep":"55","epTitle":"東京第1結界②","epTitleKo":"도쿄 제1결계 2","title":"〜末に — 오랜 노력 끝에","watch":"55화 후반부 · 히구루마를 만나기로 결심하는 이타도리","scene":"이타도리는 사멸회유의 룰을 바꾸려면 점수가 필요하다는 사실을 다시 떠올린다. 고민 끝에 그는 위험을 무릅쓰고 점수가 많은 히구루마를 직접 찾아가 이야기해 보기로 결심한다.","lines":[{"who":"이타도리","ja":"色々考えた末に、あの人に会うことに決めた。","kana":"いろいろ かんがえた すえに、あの ひとに あう ことに きめた。","ko":"여러 가지로 생각한 끝에 그 사람을 만나기로 했어."},{"who":"히구루마","ja":"悩んだ末に、俺はこのゲームに加わったんだ。","kana":"なやんだ すえに、おれは この ゲームに くわわったんだ。","ko":"고민 끝에 나는 이 게임에 들어온 거다."},{"who":"이타도리","ja":"交渉の末に点がもらえたら、ルールを一つ足せる。","kana":"こうしょうの すえに てんが もらえたら、ルールを ひとつ たせる。","ko":"교섭 끝에 점수를 받으면 룰을 하나 추가할 수 있어."}],"words":[{"w":"苦労","r":"くろう","ko":"고생"},{"w":"妥協","r":"だきょう","ko":"타협"},{"w":"交渉","r":"こうしょう","ko":"교섭, 협상"},{"w":"和解","r":"わかい","ko":"화해"},{"w":"検討","r":"けんとう","ko":"검토"},{"w":"正義","r":"せいぎ","ko":"정의"},{"w":"説得","r":"せっとく","ko":"설득"},{"w":"粘る","r":"ねばる","ko":"끈질기게 버티다"}],"grammar":{"point":"〜末に","desc":"동사 た형 + 末に(명사는 명사 + の + 末に)는 '오랫동안 ~한 끝에'라는 뜻입니다. 한국어 '~한 끝에'와 거의 같고, 충분히 고민하거나 고생한 과정을 거쳐 어떤 결론·결과에 이르렀음을 말합니다. あげく와 달리 결과가 좋든 나쁘든 쓸 수 있고, 특히 '결심했다·성공했다' 같은 긍정적 결론에 자연스럽습니다. 문장체에 가까워 보고·발표에서 자주 씁니다.","ex":[{"ja":"長い交渉の末に、ようやく契約が成立しました。","kana":"ながい こうしょうの すえに、ようやく けいやくが せいりつ しました。","ko":"긴 협상 끝에 드디어 계약이 성사되었습니다."},{"ja":"家族と話し合った末に、保険を見直すことにしました。","kana":"かぞくと はなしあった すえに、ほけんを みなおす ことに しました。","ko":"가족과 의논한 끝에 보험을 재검토하기로 했습니다."}]},"convert":{"anime":"ガチで悩んだ末に決めたんだよ。","real":"慎重に検討した末に、決定いたしました。","note":"ガチで는 '진짜로'라는 젊은 층 속어이고 〜んだよ는 반말입니다. 회사에서는 慎重に検討した(신중히 검토한)와 いたしました로 무게 있게 전합니다."},"mission":"오래 고민하거나 고생한 끝에 이룬 일을 〜末に로 말해 보세요. (예: 자격증 취득, 큰 계약, 이직)","missionEx":{"ja":"何度も説得した末に、お客様が契約してくださいました。","kana":"なんども せっとく した すえに、おきゃくさまが けいやく して くださいました。","ko":"몇 번이나 설득한 끝에 고객님이 계약해 주셨습니다."},"quiz":[{"q":"「고생한 끝에 성공했다」를 일본어로?","choices":["苦労する末に、成功した。","苦労の末で、成功した。","苦労した末に、成功した。"],"a":2,"why":"동사 た형 + 末に가 올바른 형태입니다."},{"q":"あげく와 末に의 차이로 맞는 것은?","choices":["末に는 좋은 결과에도 자연스럽다","末に는 나쁜 결과에만 쓴다","둘은 완전히 같다"],"a":0,"why":"あげく는 주로 부정적 결과, 末に는 좋은 결과에도 씁니다."},{"q":"「交渉」의 뜻은?","choices":["검토","교섭, 협상","설득"],"a":1,"why":"交渉(こうしょう)은 '교섭, 협상'입니다."}]},"310":{"day":310,"ep":"55","epTitle":"東京第1結界②","epTitleKo":"도쿄 제1결계 2","title":"〜きり — ~한 채로, ~한 이후로 / ~뿐","watch":"55화 마지막 · 이타도리와 히구루마의 첫 대면","scene":"결계 안에서 후시구로와 따로 움직이게 된 이타도리는 마침내 히구루마와 마주한다. 히구루마는 말없이 이타도리를 바라보다가, 둘만의 대화를 하자며 자신의 영역으로 그를 끌어들이려 한다.","lines":[{"who":"이타도리","ja":"伏黒と別れたきり、全然連絡が取れないんだよな。","kana":"ふしぐろと わかれた きり、ぜんぜん れんらくが とれないんだよな。","ko":"후시구로랑 헤어진 뒤로 연락이 전혀 안 되네."},{"who":"이타도리","ja":"あの人、さっきから黙ったきり、こっちを見てる。","kana":"あの ひと、さっきから だまった きり、こっちを みてる。","ko":"저 사람, 아까부터 입을 다문 채로 이쪽을 보고 있어."},{"who":"히구루마","ja":"ここから先は、君と二人きりで話がしたい。","kana":"ここから さきは、きみと ふたりきりで はなしが したい。","ko":"여기서부터는 너와 단둘이서 이야기하고 싶다."}],"words":[{"w":"音信不通","r":"おんしんふつう","ko":"연락 두절"},{"w":"沈黙","r":"ちんもく","ko":"침묵"},{"w":"無言","r":"むごん","ko":"말이 없음"},{"w":"以来","r":"いらい","ko":"이래, 그 후로"},{"w":"消息","r":"しょうそく","ko":"소식"},{"w":"じっと","r":"じっと","ko":"가만히, 꼼짝 않고"},{"w":"行方不明","r":"ゆくえふめい","ko":"행방불명"},{"w":"しんと","r":"しんと","ko":"쥐 죽은 듯 조용히"}],"grammar":{"point":"〜きり","desc":"〜きり는 크게 두 가지로 씁니다. ① 동사 た형 + きり: '~한 채로 (그 뒤로 변화가 없다)'. 出かけたきり帰らない(나간 채 돌아오지 않는다)처럼 뒤에 부정적인 내용이 옵니다. ② 명사 + きり: '~뿐, ~만'. 二人きり(단둘이), 一回きり(딱 한 번)처럼 씁니다. 회화에서는 っきり(あれっきり, それっきり)로도 자주 들립니다.","ex":[{"ja":"部長は朝出かけたきり、まだ戻っていません。","kana":"ぶちょうは あさ でかけた きり、まだ もどって いません。","ko":"부장님은 아침에 나간 채로 아직 돌아오지 않았습니다."},{"ja":"一度会ったきりのお客様から、返事が来ました。","kana":"いちど あった きりの おきゃくさまから、へんじが きました。","ko":"딱 한 번 만났던 고객님에게서 답장이 왔습니다."}]},"convert":{"anime":"あいつ、出てったきり連絡ねーし。","real":"担当の者は外出したきり、まだ戻っておりません。","note":"出てった·ねーし는 거친 축약형 반말입니다. 고객 응대에서는 あいつ 대신 担当の者(담당자)라고 하고, 〜ておりません으로 자기 쪽을 낮춥니다."},"mission":"연락이 끊긴 사람이나 한 번뿐이었던 경험을 〜きり로 말해 보세요. (예: 옛 고객, 대학 친구, 한 번 가 본 여행지)","missionEx":{"ja":"大学の友達とは、卒業したきり会っていません。","kana":"だいがくの ともだちとは、そつぎょう した きり あって いません。","ko":"대학 친구와는 졸업한 뒤로 만나지 못했습니다."},"quiz":[{"q":"「단둘이서」를 일본어로?","choices":["二人だけきり","二人ずつ","二人きり"],"a":2,"why":"명사 + きり는 '~뿐'이라는 뜻으로, 二人きり는 '단둘이'입니다."},{"q":"「彼は出かけたきり、帰ってこない」의 뜻은?","choices":["그는 나간 채로 돌아오지 않는다.","그는 나가자마자 돌아왔다.","그는 나가려고 한다."],"a":0,"why":"た형 + きり는 '~한 채로 (그 뒤 변화 없음)'입니다."},{"q":"「音信不通」의 뜻은?","choices":["침묵","연락 두절","행방불명"],"a":1,"why":"音信不通(おんしんふつう)는 연락이 끊긴 상태입니다."}]},"311":{"day":311,"ep":"56","epTitle":"東京第1結界③","epTitleKo":"도쿄 제1결계 3","title":"존경어 총정리 — いらっしゃる・お〜になる","watch":"56화 전반부 · 히구루마의 영역전개와 재판의 시작","scene":"히구루마가 영역을 펼치자 주위가 법정처럼 바뀌고, 식신 저지맨이 재판을 진행한다. 이 영역 안에서는 폭력이 금지되고, 이타도리는 시부야에서 일어난 일에 대해 피고로서 심리를 받게 된다.","lines":[{"who":"이타도리","ja":"日車さんは、前は弁護士をなさっていたんですよね。","kana":"ひぐるまさんは、まえは べんごしを なさって いたんですよね。","ko":"히구루마 씨는 전에 변호사를 하셨던 거죠?"},{"who":"히구루마","ja":"ここは俺の法廷だ。君が罪を認めるかどうかを問う。","kana":"ここは おれの ほうていだ。きみが つみを みとめるか どうかを とう。","ko":"여기는 나의 법정이다. 네가 죄를 인정하는지 묻겠다."},{"who":"이타도리","ja":"証拠をご覧になったなら、もうお分かりですよね。","kana":"しょうこを ごらんに なったなら、もう おわかりですよね。","ko":"증거를 보셨다면 이미 아시겠죠."}],"words":[{"w":"法廷","r":"ほうてい","ko":"법정"},{"w":"起訴","r":"きそ","ko":"기소"},{"w":"陳述","r":"ちんじゅつ","ko":"진술"},{"w":"黙秘","r":"もくひ","ko":"묵비"},{"w":"召し上がる","r":"めしあがる","ko":"드시다 (食べる·飲む의 존경어)"},{"w":"おっしゃる","r":"おっしゃる","ko":"말씀하시다 (言う의 존경어)"},{"w":"ご覧になる","r":"ごらんになる","ko":"보시다 (見る의 존경어)"},{"w":"いらっしゃる","r":"いらっしゃる","ko":"계시다, 오시다, 가시다"}],"grammar":{"point":"존경어 총정리","desc":"존경어는 상대(고객·윗사람)의 행동을 높이는 말입니다. ① 특별한 동사: いる·行く·来る→いらっしゃる, 言う→おっしゃる, 食べる·飲む→召し上がる, 見る→ご覧になる, する→なさる, 知っている→ご存じだ. ② 규칙형: お + ます형 + になる(お待ちになる), ご + 한자어 + になる(ご利用になる). ③ 가벼운 존경: 〜れる・〜られる(読まれる・来られる). 주어가 '상대'일 때만 쓰고, 나 자신의 행동에는 절대 쓰지 않는 것이 핵심입니다.","ex":[{"ja":"社長は何時ごろいらっしゃいますか。","kana":"しゃちょうは なんじごろ いらっしゃいますか。","ko":"사장님은 몇 시쯤 오십니까?"},{"ja":"先ほどおっしゃった条件で、もう一度お調べになりますか。","kana":"さきほど おっしゃった じょうけんで、もう いちど おしらべに なりますか。","ko":"아까 말씀하신 조건으로 다시 한번 알아보시겠습니까?"}]},"convert":{"anime":"日車さん、それマジで言ってんの？","real":"日車さん、それは本気でおっしゃっているんですか。","note":"言ってんの는 言っているの의 반말 축약입니다. 상대가 한 말이므로 言う를 존경어 おっしゃる로 바꾸고, マジで는 本気で로 바꿉니다."},"mission":"일본인 고객이 사무실에 찾아왔습니다. 존경어로 '무엇을 드시겠어요?', '이 자료를 보셨나요?'를 물어보세요.","missionEx":{"ja":"お飲み物は何を召し上がりますか。こちらの資料はもうご覧になりましたか。","kana":"おのみものは なにを めしあがりますか。こちらの しりょうは もう ごらんに なりましたか。","ko":"음료는 무엇을 드시겠어요? 이 자료는 벌써 보셨나요?"},"quiz":[{"q":"「言う」의 존경어는?","choices":["申す","おっしゃる","伺う"],"a":1,"why":"言う의 존경어는 おっしゃる, 겸양어는 申す입니다."},{"q":"고객에게 「기다리시겠습니까?」를 바르게 말한 것은?","choices":["お待ちになりますか。","お待ちしますか。","待たせますか。"],"a":0,"why":"상대 행동은 お + ます형 + になる(존경)입니다. お待ちする는 겸양입니다."},{"q":"「陳述」의 읽기는?","choices":["ちんじゅつ","じんじゅつ","ちんしゅつ"],"a":0,"why":"陳述(ちんじゅつ)는 진술입니다."}]},"312":{"day":312,"ep":"56","epTitle":"東京第1結界③","epTitleKo":"도쿄 제1결계 3","title":"겸양어 총정리 — 伺う・お〜する","watch":"56화 중반부 · 피고 이타도리의 진술","scene":"저지맨이 시부야 사건에 대한 혐의를 제시하자, 이타도리는 변명하지 않고 그날의 일을 자신의 책임으로 받아들인다. 히구루마는 그 정직한 태도에 흔들리면서도 판결을 내린다.","lines":[{"who":"이타도리","ja":"渋谷で起きたこと、俺から全部お話しします。","kana":"しぶやで おきた こと、おれから ぜんぶ おはなし します。","ko":"시부야에서 일어난 일, 제가 전부 말씀드릴게요."},{"who":"이타도리","ja":"日車さんのことは、噂で前から存じておりました。","kana":"ひぐるまさんの ことは、うわさで まえから ぞんじて おりました。","ko":"히구루마 씨에 대해서는 소문으로 전부터 알고 있었습니다."},{"who":"히구루마","ja":"ずいぶん正直な被告だな。では、判決を言い渡す。","kana":"ずいぶん しょうじきな ひこくだな。では、はんけつを いいわたす。","ko":"꽤 정직한 피고군. 그럼 판결을 선고하겠다."}],"words":[{"w":"申す","r":"もうす","ko":"말씀드리다 (言う의 겸양어)"},{"w":"参る","r":"まいる","ko":"가다, 오다 (겸양어)"},{"w":"伺う","r":"うかがう","ko":"찾아뵙다, 여쭙다"},{"w":"拝見する","r":"はいけんする","ko":"삼가 보다 (見る의 겸양어)"},{"w":"いただく","r":"いただく","ko":"받다, 먹다 (겸양어)"},{"w":"存じる","r":"ぞんじる","ko":"알다, 생각하다 (겸양어)"},{"w":"被告","r":"ひこく","ko":"피고"},{"w":"正直","r":"しょうじき","ko":"정직, 솔직함"}],"grammar":{"point":"겸양어 총정리","desc":"겸양어는 나(우리 회사)의 행동을 낮춰서 상대를 높이는 말입니다. ① 특별한 동사: 行く·来る→参る, 訪ねる·聞く→伺う, 言う→申す·申し上げる, 見る→拝見する, もらう·食べる→いただく, 知っている→存じている, する→いたす. ② 규칙형: お + ます형 + する(お持ちする), ご + 한자어 + する(ご案内する). 주어가 '나'일 때만 쓰며, 고객의 행동에 겸양어를 쓰면 큰 실례가 됩니다.","ex":[{"ja":"明日の十時に、御社へ伺います。","kana":"あしたの じゅうじに、おんしゃへ うかがいます。","ko":"내일 10시에 귀사로 찾아뵙겠습니다."},{"ja":"資料を拝見しました。後ほどお電話いたします。","kana":"しりょうを はいけん しました。のちほど おでんわ いたします。","ko":"자료를 잘 보았습니다. 나중에 전화드리겠습니다."}]},"convert":{"anime":"じゃ、俺がそっち行くわ。","real":"では、私がそちらに伺います。","note":"行くわ(남성의 가벼운 반말)는 고객에게 쓸 수 없습니다. 내가 가는 것이므로 行く를 겸양어 伺う(参る)로 바꾸고, そっち는 そちら로 바꿉니다."},"mission":"일본인 고객에게 전화로 방문 약속을 잡습니다. 겸양어로 '자료는 봤습니다', '내일 찾아뵙겠습니다'를 말해 보세요.","missionEx":{"ja":"資料は拝見しました。明日の午後、そちらに伺ってもよろしいでしょうか。","kana":"しりょうは はいけん しました。あしたの ごご、そちらに うかがっても よろしいでしょうか。","ko":"자료는 잘 보았습니다. 내일 오후에 그쪽으로 찾아봬도 괜찮을까요?"},"quiz":[{"q":"내가 고객의 자료를 '본' 것을 겸양어로?","choices":["ご覧になりました","拝見しました","見られました"],"a":1,"why":"내 행동이므로 겸양어 拝見する입니다. ご覧になる는 상대를 높이는 존경어입니다."},{"q":"「제가 안내해 드리겠습니다」로 맞는 것은?","choices":["私がご案内になります。","私が案内なさいます。","私がご案内します。"],"a":2,"why":"내 행동은 ご + 한자어 + する(겸양)입니다."},{"q":"「伺う」의 뜻이 아닌 것은?","choices":["주다","찾아뵙다","여쭙다"],"a":0,"why":"伺う는 訪ねる(방문하다)·聞く(묻다)의 겸양어입니다."}]},"313":{"day":313,"ep":"56","epTitle":"東京第1結界③","epTitleKo":"도쿄 제1결계 3","title":"정중어·미화어 お / ご — お名前・ご住所","watch":"56화 후반부 · 처형인의 검과 맞서는 이타도리","scene":"판결이 내려지자 히구루마의 손에는 닿기만 해도 끝장인 '처형인의 검'이 생긴다. 이타도리는 담담하게 결과를 받아들이면서도, 아직 해야 할 일이 남았다며 쓰러지지 않고 맞선다.","lines":[{"who":"히구루마","ja":"判決は最も重い刑だ。この剣が、その答えになる。","kana":"はんけつは もっとも おもい けいだ。この けんが、その こたえに なる。","ko":"판결은 가장 무거운 형벌이다. 이 검이 그 답이 된다."},{"who":"이타도리","ja":"丁寧なご説明どうも。でも俺は、まだ終われない。","kana":"ていねいな ごせつめい どうも。でも おれは、まだ おわれない。","ko":"친절한 설명 고마워. 그래도 난 아직 끝날 수 없어."},{"who":"히구루마","ja":"お互い、引けない理由があるということか。","kana":"おたがい、ひけない りゆうが ある と いう ことか。","ko":"서로 물러설 수 없는 이유가 있다는 건가."}],"words":[{"w":"意向","r":"いこう","ko":"의향"},{"w":"処分","r":"しょぶん","ko":"처분"},{"w":"判定","r":"はんてい","ko":"판정"},{"w":"執行","r":"しっこう","ko":"집행"},{"w":"有罪","r":"ゆうざい","ko":"유죄"},{"w":"刑罰","r":"けいばつ","ko":"형벌"},{"w":"異議","r":"いぎ","ko":"이의"},{"w":"剣","r":"けん","ko":"검, 칼"}],"grammar":{"point":"정중어·미화어 お / ご","desc":"명사 앞에 お·ご를 붙이면 말이 정중하고 부드러워집니다. 원칙적으로 고유 일본어(和語)에는 お(お名前·お金·お茶), 한자어(漢語)에는 ご(ご住所·ご説明·ご予約)를 붙입니다. 다만 お電話·お時間·お食事처럼 한자어인데 お가 붙는 예외도 많으니 단어째 외우세요. 외래어(コーヒー·メール)에는 보통 붙이지 않습니다. 또 상대 것에 붙이면 존경(ご意見=고객님의 의견), 나의 행동에 붙이면 겸양(ご連絡します)이 됩니다.","ex":[{"ja":"こちらにお名前とご住所をご記入ください。","kana":"こちらに おなまえと ごじゅうしょを ごきにゅう ください。","ko":"여기에 성함과 주소를 기입해 주십시오."},{"ja":"ご都合のいいお時間を教えていただけますか。","kana":"ごつごうの いい おじかんを おしえて いただけますか。","ko":"편하신 시간을 알려 주실 수 있을까요?"}]},"convert":{"anime":"説明サンキュー。じゃ、名前と住所書いて。","real":"ご説明ありがとうございます。では、お名前とご住所をご記入ください。","note":"サンキュー·書いて는 친구끼리의 가벼운 말입니다. 고객 서류를 받을 때는 명사마다 お·ご를 붙이고, ご記入ください로 정중하게 부탁합니다."},"mission":"보험 상담 창구에서 일본인 고객을 맞이합니다. お·ご를 넣어 이름, 주소, 예약 여부를 물어보세요.","missionEx":{"ja":"ご予約のお客様ですか。お名前をお願いいたします。","kana":"ごよやくの おきゃくさまですか。おなまえを おねがい いたします。","ko":"예약하신 고객님이신가요? 성함을 부탁드립니다."},"quiz":[{"q":"「住所」에 붙는 미화어는?","choices":["お住所","ご住所","おご住所"],"a":1,"why":"住所는 한자어이므로 ご를 붙여 ご住所라고 합니다."},{"q":"한자어인데 お가 붙는 예외는?","choices":["お電話","お予約","お説明"],"a":0,"why":"電話는 한자어지만 관용적으로 お電話라고 합니다."},{"q":"「執行」의 뜻은?","choices":["판정","집행","처분"],"a":1,"why":"執行(しっこう)는 집행. 刑の執行 = 형 집행."}]},"314":{"day":314,"ep":"56","epTitle":"東京第1結界③","epTitleKo":"도쿄 제1결계 3","title":"비즈니스 전화 표현 — 少々お待ちください","watch":"56화 마지막 · 히구루마가 점수를 넘기고 룰을 추가하는 장면","scene":"싸움 끝에 히구루마는 이타도리의 진심을 받아들이고 칼을 거둔다. 그는 자신의 점수를 이타도리에게 넘겨주고, 이타도리는 결계의 안내 식신 코가네를 불러 새 룰 추가를 신청한다.","lines":[{"who":"히구루마","ja":"俺の得点を君に譲ろう。好きに使ってくれ。","kana":"おれの とくてんを きみに ゆずろう。すきに つかって くれ。","ko":"내 점수를 너에게 넘기겠다. 마음대로 써라."},{"who":"이타도리","ja":"もしもし、コガネ？ルールを一つ追加したいんだけど。","kana":"もしもし、コガネ？ルールを ひとつ ついか したいんだけど。","ko":"여보세요, 코가네? 룰을 하나 추가하고 싶은데."},{"who":"코가네","ja":"ルールの追加ですね。少々お待ちください！","kana":"ルールの ついかですね。しょうしょう おまち ください！","ko":"룰 추가 말씀이시군요. 잠시만 기다려 주세요!"}],"words":[{"w":"取り次ぐ","r":"とりつぐ","ko":"(전화를) 연결하다, 전하다"},{"w":"内線","r":"ないせん","ko":"내선"},{"w":"不在","r":"ふざい","ko":"부재"},{"w":"少々","r":"しょうしょう","ko":"잠시, 조금"},{"w":"用件","r":"ようけん","ko":"용건"},{"w":"得点","r":"とくてん","ko":"득점, 점수"},{"w":"譲る","r":"ゆずる","ko":"양보하다, 넘겨주다"},{"w":"外す","r":"はずす","ko":"떼다, (자리를) 비우다"}],"grammar":{"point":"비즈니스 전화 표현","desc":"받을 때: はい、〇〇保険でございます。(네, ○○보험입니다.)\n바꿔 줄 때: 少々お待ちください。(잠시만 기다려 주세요.)\n부재 시: あいにく〇〇は席を外しております。(공교롭게도 ○○는 자리를 비웠습니다.) — 자기 회사 사람은 さん 없이 부릅니다.\n제안: 折り返しお電話いたしましょうか。/ ご伝言を承りましょうか。(다시 전화드릴까요? / 메시지를 남겨 드릴까요?)\n마무리: 失礼いたします。(전화 끊을 때 인사)","ex":[{"ja":"あいにく担当の田中は席を外しております。","kana":"あいにく たんとうの たなかは せきを はずして おります。","ko":"공교롭게도 담당 다나카는 자리를 비웠습니다."},{"ja":"戻りましたら、折り返しお電話いたしましょうか。","kana":"もどりましたら、おりかえし おでんわ いたしましょうか。","ko":"돌아오면 다시 전화드리도록 할까요?"}]},"convert":{"anime":"今いないから、また後でかけて。","real":"あいにく席を外しておりますので、戻り次第、折り返しお電話いたします。","note":"いないから·かけて는 상대에게 다시 걸라고 떠넘기는 반말입니다. 비즈니스 전화에서는 席を外しております로 부재를 알리고, 이쪽에서 折り返し 전화하겠다고 제안하는 것이 기본입니다."},"mission":"일본인 고객이 전화로 '담당 ○○ 씨 계세요?'라고 묻습니다. 담당자가 부재 중이라고 알리고, 다시 전화드릴지·전화번호를 받을지 2~3턴으로 응대해 보세요.","missionEx":{"ja":"あいにく担当は外出しております。お電話番号を伺ってもよろしいでしょうか。","kana":"あいにく たんとうは がいしゅつ して おります。おでんわばんごうを うかがっても よろしいでしょうか。","ko":"공교롭게도 담당자는 외출 중입니다. 전화번호를 여쭤봐도 될까요?"},"quiz":[{"q":"「잠시만 기다려 주세요」의 정중한 표현은?","choices":["ちょっと待って。","少し待ってくれ。","少々お待ちください。"],"a":2,"why":"비즈니스 전화에서는 少々お待ちください가 기본입니다."},{"q":"고객에게 자기 회사 사람을 말할 때 맞는 것은?","choices":["田中さんは席を外していらっしゃいます。","田中は席を外しております。","田中様は席を外しています。"],"a":1,"why":"외부 사람에게 자기 회사 사람은 さん 없이 부르고 겸양 표현(〜ております)을 씁니다."},{"q":"「取り次ぐ」의 전화 표현 뜻은?","choices":["연결해 주다","전화를 끊다","메시지를 남기다"],"a":0,"why":"お取り次ぎいたします는 '(담당자에게) 연결해 드리겠습니다'입니다."}]},"316":{"day":316,"ep":"57","epTitle":"東京第1結界④","epTitleKo":"도쿄 제1결계 4","title":"〜まで — ~까지도, ~마저 (강조)","watch":"57화 전반부 · 히구루마의 영역 안에서 재판이 시작되는 장면","scene":"도쿄 제1결계에서 이타도리는 전직 변호사 히구루마와 마주친다. 히구루마의 영역이 펼쳐지자 싸움은 '재판'의 형태가 되고, 이타도리는 시부야에서 일어난 일에 대해 심판을 받는다. 유죄가 되면 술식까지 빼앗길 수 있는 긴장된 상황이다.","lines":[{"who":"히구루마","ja":"有罪になれば、術式まで没収されるぞ。","kana":"ゆうざいに なれば、じゅつしき まで ぼっしゅう される ぞ。","ko":"유죄가 되면 술식까지 몰수된다."},{"who":"이타도리","ja":"渋谷のことは、俺がやった。罪まで隠す気はない。","kana":"しぶやの ことは、おれが やった。つみ まで かくす きは ない。","ko":"시부야 일은 내가 한 거야. 죄까지 숨길 생각은 없어."},{"who":"히구루마","ja":"元弁護士の俺まで驚かせるとは、変わった被告人だ。","kana":"もと べんごしの おれ まで おどろかせる とは、かわった ひこくにん だ。","ko":"전직 변호사인 나까지 놀라게 하다니, 별난 피고인이군."}],"words":[{"w":"検察官","r":"けんさつかん","ko":"검찰관, 검사"},{"w":"原告","r":"げんこく","ko":"원고"},{"w":"加害者","r":"かがいしゃ","ko":"가해자"},{"w":"自白","r":"じはく","ko":"자백"},{"w":"量刑","r":"りょうけい","ko":"양형"},{"w":"無罪","r":"むざい","ko":"무죄"},{"w":"法律","r":"ほうりつ","ko":"법률"},{"w":"審理","r":"しんり","ko":"심리"}],"grammar":{"point":"〜まで (강조: ~까지도)","desc":"まで는 원래 '~까지'(범위의 끝)를 나타내지만, '보통은 그렇지 않을 것까지 포함해서'라는 놀람·강조의 뜻으로도 씁니다. 한국어 '~까지(도)', '~마저'와 거의 같습니다. 社長まで来た(사장님까지 왔다)처럼 명사에 바로 붙이고, 조사가 있으면 〜にまで, 〜とまで처럼 겹쳐 씁니다. 긍정적인 놀람에도, '이것까지?' 하는 불만에도 모두 쓸 수 있습니다.","ex":[{"ja":"今日の説明会には、社長まで出席しました。","kana":"きょうの せつめいかいには、しゃちょう まで しゅっせき しました。","ko":"오늘 설명회에는 사장님까지 참석했습니다."},{"ja":"最近は日曜日にまで、仕事の電話が来ます。","kana":"さいきんは にちようびに まで、しごとの でんわが きます。","ko":"요즘은 일요일에까지 업무 전화가 옵니다."}]},"convert":{"anime":"俺まで巻き込むなよ。","real":"私にまでご連絡いただき、恐縮です。","note":"巻き込むなよ는 불만 섞인 반말입니다. 업무에서는 まで를 '저에게까지 신경 써 주셔서'라는 감사·겸손의 뉘앙스로 바꿔 쓰는 편이 자연스럽습니다."},"mission":"고객의 가족까지 상담에 함께 와 준 상황입니다. 〜まで를 써서 감사 인사를 해 보세요.","missionEx":{"ja":"ご家族の皆様まで来ていただき、ありがとうございます。","kana":"ごかぞくの みなさま まで きて いただき、ありがとう ございます。","ko":"가족분들까지 와 주셔서 감사합니다."},"quiz":[{"q":"'사장님까지 참석했습니다'를 일본어로?","choices":["社長まで出席しました。","社長から出席しました。","社長だけ出席しました。"],"a":0,"why":"'~까지도'의 강조는 まで. から는 '~부터', だけ는 '~만'입니다."},{"q":"「自白」의 뜻은?","choices":["판결","자백","법률"],"a":1,"why":"自白(じはく)는 자백. 판결은 判決, 법률은 法律입니다."},{"q":"「無罪」의 읽기는?","choices":["むさい","むざい","ぶざい"],"a":1,"why":"無罪(むざい)는 무죄. 유죄는 有罪(ゆうざい)입니다."}]},"317":{"day":317,"ep":"57","epTitle":"東京第1結界④","epTitleKo":"도쿄 제1결계 4","title":"〜なんて — ~하다니, ~따위 (놀람·경시)","watch":"57화 중반 · 이타도리가 변명 없이 자신의 죄를 인정하는 장면","scene":"재판에서 이타도리는 핑계를 대지 않고 시부야의 일을 자기 책임으로 받아들인다. 법정에서 수많은 거짓말과 변명을 보아 온 히구루마는 그런 이타도리의 태도에 당황한다. 히구루마는 과거 법정에서 정의가 무너지는 것을 보며 지쳐 버린 사람이었다.","lines":[{"who":"히구루마","ja":"自分から罪を認めるなんて、珍しい被告人だな。","kana":"じぶんから つみを みとめる なんて、めずらしい ひこくにん だな。","ko":"스스로 죄를 인정하다니, 드문 피고인이군."},{"who":"이타도리","ja":"言い訳なんてしない。全部、俺の責任だ。","kana":"いいわけ なんて しない。ぜんぶ、おれの せきにん だ。","ko":"변명 따위 안 해. 전부 내 책임이야."},{"who":"히구루마","ja":"正義なんて、あの法廷にはどこにもなかった。","kana":"せいぎ なんて、あの ほうていには どこにも なかった。","ko":"정의 따위, 그 법정에는 어디에도 없었어."}],"words":[{"w":"弁解","r":"べんかい","ko":"변명, 해명"},{"w":"言い訳","r":"いいわけ","ko":"변명, 핑계"},{"w":"開き直る","r":"ひらきなおる","ko":"정색하고 나오다, 뻔뻔하게 굴다"},{"w":"責任転嫁","r":"せきにんてんか","ko":"책임 전가"},{"w":"潔い","r":"いさぎよい","ko":"깨끗하다, 떳떳하다"},{"w":"偽証","r":"ぎしょう","ko":"위증"},{"w":"誠意","r":"せいい","ko":"성의"},{"w":"疑う","r":"うたがう","ko":"의심하다"}],"grammar":{"point":"〜なんて","desc":"なんて는 두 가지로 씁니다. ① 문장 끝에서 '~하다니!'라는 놀람·감탄: 合格するなんて(합격하다니). ② 명사 뒤에서 '~따위, ~같은 건'이라는 경시: 言い訳なんて(변명 따위). 동사·형용사는 보통형에 그대로 붙입니다. ②는 상대가 아끼는 것에 쓰면 무례해질 수 있으니, 업무에서는 주로 ①의 놀람·감탄으로 씁니다.","ex":[{"ja":"こんなに早く契約が決まるなんて、驚きました。","kana":"こんなに はやく けいやくが きまる なんて、おどろきました。","ko":"이렇게 빨리 계약이 성사되다니 놀랐습니다."},{"ja":"以前は保険なんて必要ないと思っていました。","kana":"いぜんは ほけん なんて ひつよう ない と おもって いました。","ko":"예전에는 보험 같은 건 필요 없다고 생각했어요."}]},"convert":{"anime":"謝るなんて、らしくねえな。","real":"わざわざご丁寧に、ありがとうございます。","note":"らしくねえな는 거친 반말이고, 상대의 사과에 '너답지 않다'고 하면 실례입니다. 고객이 사과하거나 신경 써 줄 때는 감사로 받는 말투가 좋습니다."},"mission":"오래 고민하던 고객이 드디어 가입을 결정했습니다. 〜なんて를 써서 기쁜 놀라움을 표현해 보세요.","missionEx":{"ja":"今日決めていただけるなんて、本当にうれしいです。","kana":"きょう きめて いただける なんて、ほんとうに うれしい です。","ko":"오늘 결정해 주시다니 정말 기쁩니다."},"quiz":[{"q":"'변명 따위 안 해'를 일본어로?","choices":["言い訳でもしない。","言い訳さえする。","言い訳なんてしない。"],"a":2,"why":"'~따위'라는 경시는 なんて로 나타냅니다."},{"q":"「偽証」의 읽기는?","choices":["ぎしょう","いしょう","ぎせい"],"a":0,"why":"偽証(ぎしょう)는 위증입니다."},{"q":"「潔い」의 뜻은?","choices":["깨끗하다, 떳떳하다","뻔뻔하다","서투르다"],"a":0,"why":"潔い(いさぎよい)는 미련 없이 깨끗한 태도입니다. 潔く認める = 깨끗이 인정하다."}]},"318":{"day":318,"ep":"57","epTitle":"東京第1結界④","epTitleKo":"도쿄 제1결계 4","title":"〜など — ~따위, ~같은 (낮추어 말하기)","watch":"57화 후반부 · 재판을 마친 히구루마가 자신의 과거를 돌아보는 장면","scene":"변호사 시절 히구루마는 의뢰인을 지키려 최선을 다했지만 결과는 늘 허무했다. 이타도리와 맞서며 그는 자신이 무엇을 잃어버렸는지 다시 생각하게 된다. 이타도리 역시 자신은 아직 누구도 제대로 구하지 못했다고 스스로를 낮춘다.","lines":[{"who":"히구루마","ja":"俺など、依頼人一人守れなかった元弁護士だ。","kana":"おれ など、いらいにん ひとり まもれなかった もと べんごし だ。","ko":"나 같은 건 의뢰인 한 명 지키지 못한 전직 변호사야."},{"who":"이타도리","ja":"俺なんか…いや、俺などまだまだ実力が足りない。","kana":"おれ なんか…いや、おれ など まだまだ じつりょくが たりない。","ko":"나 같은 건… 아니, 난 아직 실력이 부족해."},{"who":"히구루마","ja":"過去の努力など、もう何の価値もないと思っていた。","kana":"かこの どりょく など、もう なんの かちも ない と おもって いた。","ko":"과거의 노력 따위 이제 아무 가치도 없다고 생각했었다."}],"words":[{"w":"過去","r":"かこ","ko":"과거"},{"w":"依頼人","r":"いらいにん","ko":"의뢰인"},{"w":"尊敬","r":"そんけい","ko":"존경"},{"w":"見返り","r":"みかえり","ko":"대가, 보답"},{"w":"徒労","r":"とろう","ko":"헛수고"},{"w":"足りない","r":"たりない","ko":"부족하다, 모자라다"},{"w":"むなしい","r":"むなしい","ko":"허무하다"},{"w":"骨折り損","r":"ほねおりぞん","ko":"애쓴 보람이 없음"}],"grammar":{"point":"〜など (낮추어 말하기)","desc":"など는 '~등'이라는 예시 외에, 자기 자신이나 어떤 대상을 낮추어 '~같은 사람/것', '~따위'라고 말할 때도 씁니다. 私などまだまだです(저 같은 건 아직 멀었습니다)처럼 자신을 낮추면 겸손한 표현이 되고, 남이나 남의 것에 쓰면 깔보는 말이 됩니다. 구어에서는 なんか가 같은 역할을 하지만, など가 더 격식 있고 업무에 어울립니다. 또 お茶などいかがですか처럼 권유를 부드럽게 할 때도 씁니다.","ex":[{"ja":"私などでよろしければ、喜んでお手伝いします。","kana":"わたし など で よろしければ、よろこんで おてつだい します。","ko":"저 같은 사람이라도 괜찮으시다면 기꺼이 돕겠습니다."},{"ja":"お待ちの間、お茶などいかがですか。","kana":"おまちの あいだ、おちゃ など いかが ですか。","ko":"기다리시는 동안 차라도 한 잔 어떠세요?"}]},"convert":{"anime":"俺なんか、まだまだだよ。","real":"私などまだまだ勉強中です。","note":"俺なんか는 친구끼리 쓰는 편한 겸손입니다. 칭찬을 받았을 때 고객 앞에서는 私など와 です를 써서 정중하게 겸손을 표현합니다."},"mission":"고객이 '정말 전문가시네요'라고 칭찬했습니다. 〜など를 써서 겸손하게 대답해 보세요.","missionEx":{"ja":"いえいえ、私などまだまだ勉強不足です。","kana":"いえいえ、わたし など まだまだ べんきょう ぶそく です。","ko":"아니에요, 저는 아직 공부가 부족합니다."},"quiz":[{"q":"'저 같은 사람이라도 괜찮으시다면'에 맞는 것은?","choices":["私までよろしければ","私などでよろしければ","私しかよろしければ"],"a":1,"why":"자신을 낮추는 '~같은 사람'은 など. まで는 '~까지', しか는 부정과 함께 씁니다."},{"q":"「見返りが足りない」의 뜻은?","choices":["대가가 부족하다","대가가 넘치다","대가를 잃다"],"a":0,"why":"足りない(たりない)는 '부족하다', 見返り(みかえり)는 '대가'입니다."},{"q":"「尊敬」의 읽기는?","choices":["そんきょう","そんけ","そんけい"],"a":2,"why":"尊敬(そんけい)는 존경. 尊敬語(そんけいご)는 존경어입니다."}]},"319":{"day":319,"ep":"57","epTitle":"東京第1結界④","epTitleKo":"도쿄 제1결계 4","title":"〜ものか — 절대 ~하나 봐라 (강한 부정)","watch":"57화 마지막 · 결판이 난 뒤 히구루마가 점수를 넘겨주는 장면","scene":"치열한 대결 끝에 이타도리는 다시는 누구도 버리지 않겠다는 각오를 보인다. 그 모습에 마음이 움직인 히구루마는 자신의 점수를 이타도리에게 넘겨주어, 결계에 새로운 규칙을 추가할 수 있게 돕는다. 히구루마는 예전의 세계로는 돌아가지 않겠다고 말한다.","lines":[{"who":"이타도리","ja":"二度と、誰も見捨てるものか。そう決心したんだ。","kana":"にどと、だれも みすてる ものか。そう けっしん したんだ。","ko":"두 번 다시 아무도 버리나 봐라. 그렇게 결심했어."},{"who":"히구루마","ja":"あんな場所に、今さら戻るものか。","kana":"あんな ばしょに、いまさら もどる ものか。","ko":"그런 곳에 이제 와서 돌아갈까 보냐."},{"who":"히구루마","ja":"点数は譲ってやる。後悔するなよ、虎杖。","kana":"てんすうは ゆずって やる。こうかい するなよ、いたどり。","ko":"점수는 넘겨주지. 후회하지 마라, 이타도리."}],"words":[{"w":"断じて","r":"だんじて","ko":"결단코 (+부정)"},{"w":"見捨てる","r":"みすてる","ko":"버리다, 저버리다"},{"w":"放棄","r":"ほうき","ko":"포기"},{"w":"託す","r":"たくす","ko":"맡기다, 부탁하다"},{"w":"譲渡","r":"じょうと","ko":"양도"},{"w":"誓約","r":"せいやく","ko":"서약"},{"w":"悔い","r":"くい","ko":"후회, 미련"},{"w":"誓う","r":"ちかう","ko":"맹세하다"}],"grammar":{"point":"〜ものか","desc":"〜ものか는 '절대 ~하지 않겠다', '~할까 보냐'라는 강한 부정·결심을 나타냅니다. 동사 사전형이나 い형용사에 붙이고(負けるものか = 질까 보냐), な형용사·명사는 〜なものか가 됩니다. 구어에서는 〜もんか, 여성스럽거나 정중하게는 〜ものですか라고 합니다. 감정이 강한 말이라 고객 앞보다는 혼잣말이나 각오를 말할 때 어울립니다.","ex":[{"ja":"こんなチャンスを逃すものか、と思って準備しました。","kana":"こんな ちゃんすを のがす ものか、と おもって じゅんび しました。","ko":"이런 기회를 놓칠까 보냐 하는 마음으로 준비했습니다."},{"ja":"あの店には二度と行くものか。","kana":"あの みせには にどと いく ものか。","ko":"그 가게엔 두 번 다시 가나 봐라."}]},"convert":{"anime":"負けてたまるか！","real":"最後まで全力で取り組みます。","note":"〜てたまるか, 〜ものか는 감정이 강한 반말 표현입니다. 회사나 고객 앞에서 각오를 말할 때는 '최선을 다하겠습니다'처럼 긍정문으로 바꿔 말합니다."},"mission":"어려운 자격시험(예: CFP 갱신 시험)을 앞두고 있습니다. 〜ものか로 자신의 각오를 혼잣말로 말해 보세요.","missionEx":{"ja":"今年の試験には、絶対に落ちるものか。","kana":"ことしの しけんには、ぜったいに おちる ものか。","ko":"올해 시험에는 절대 떨어지나 봐라."},"quiz":[{"q":"「負けるものか」의 뜻은?","choices":["질지도 모른다","질 리가 없지?","절대 지나 봐라"],"a":2,"why":"〜ものか는 강한 부정·결심. '질까 보냐'라는 뜻입니다."},{"q":"「断じて」 뒤에 오는 말로 자연스러운 것은?","choices":["許さない","許す","許したい"],"a":0,"why":"断じて는 부정과 함께 '결단코 ~않다'로 씁니다."},{"q":"「悔い」의 읽기는?","choices":["かい","くい","こうかい"],"a":1,"why":"悔い(くい)는 후회·미련. 悔いはない = 후회는 없다."}]},"320":{"day":320,"ep":"58","epTitle":"東京第1結界⑤","epTitleKo":"도쿄 제1결계 5","title":"〜に比べて — ~에 비해서","watch":"58화 전반부 · 후시구로가 레지 일행과 맞붙는 장면","scene":"같은 결계 안에서 후시구로는 레지가 이끄는 무리와 싸움을 벌인다. 레지는 영수증을 이용해 물건을 불러내는 독특한 술식을 쓰고, 상대는 수도 많다. 후시구로는 지금까지의 적에 비해 훨씬 까다로운 상대임을 깨닫는다.","lines":[{"who":"후시구로","ja":"さっきの連中に比べて、こいつはかなり手強い。","kana":"さっきの れんちゅうに くらべて、こいつは かなり てごわい。","ko":"아까 그 녀석들에 비해 이놈은 꽤 까다롭다."},{"who":"레지","ja":"領収書さえあれば、何でも取り出せるんだよ。","kana":"りょうしゅうしょ さえ あれば、なんでも とりだせるんだよ。","ko":"영수증만 있으면 뭐든 꺼낼 수 있다고."},{"who":"후시구로","ja":"向こうの人数に比べて、こっちは明らかに不利だ。","kana":"むこうの にんずうに くらべて、こっちは あきらかに ふり だ。","ko":"저쪽 인원수에 비하면 이쪽이 확실히 불리하다."}],"words":[{"w":"領収書","r":"りょうしゅうしょ","ko":"영수증"},{"w":"釣り銭","r":"つりせん","ko":"거스름돈"},{"w":"不利","r":"ふり","ko":"불리"},{"w":"値上がり","r":"ねあがり","ko":"가격 인상"},{"w":"手強い","r":"てごわい","ko":"만만치 않다, 벅차다"},{"w":"値下がり","r":"ねさがり","ko":"가격 인하"},{"w":"経費","r":"けいひ","ko":"경비"},{"w":"以前","r":"いぜん","ko":"이전, 예전"}],"grammar":{"point":"〜に比べて","desc":"〜に比べて는 '~에 비해서'로, 두 가지를 비교할 때 기준을 나타냅니다. 명사에 바로 붙이고(去年に比べて), 동사는 〜のに比べて로 씁니다. 〜に比べると, 문장체로는 〜に比べ도 같은 뜻입니다. 숫자·실적·상품 비교에 아주 자주 쓰여서 재무 상담에서 특히 유용합니다.","ex":[{"ja":"去年に比べて、売り上げが一割増えました。","kana":"きょねんに くらべて、うりあげが いちわり ふえました。","ko":"작년에 비해 매출이 10% 늘었습니다."},{"ja":"この商品は他社に比べて、保険料が安いです。","kana":"この しょうひんは たしゃに くらべて、ほけんりょうが やすい です。","ko":"이 상품은 타사에 비해 보험료가 쌉니다."}]},"convert":{"anime":"前よりずっと強えじゃん。","real":"以前に比べて、ずいぶん改善されましたね。","note":"強えじゃん은 거친 남성 반말입니다. 업무에서는 〜に比べて로 기준을 분명히 밝히고 です・ます로 정리하면 보고·설명에 딱 맞습니다."},"mission":"고객에게 새 플랜을 설명합니다. 〜に比べて를 써서 지금 가입한 보험과 비교해 장점을 말해 보세요.","missionEx":{"ja":"今のご契約に比べて、月々の保険料が三千円ほど減ります。","kana":"いまの ごけいやくに くらべて、つきづきの ほけんりょうが さんぜんえん ほど へります。","ko":"지금 계약에 비해 매달 보험료가 3천 엔 정도 줄어듭니다."},"quiz":[{"q":"'작년에 비해 매출이 늘었습니다'를 일본어로?","choices":["去年に比べて、売り上げが増えました。","去年を比べて、売り上げが増えました。","去年が比べて、売り上げが増えました。"],"a":0,"why":"비교의 기준은 조사 に를 써서 〜に比べて입니다."},{"q":"「値上がり」의 반대말은?","choices":["値下がり","釣り銭","不利"],"a":0,"why":"値上がり(ねあがり, 가격 인상) ↔ 値下がり(ねさがり, 가격 인하)."},{"q":"「不利」의 뜻은?","choices":["유리","불편","불리"],"a":2,"why":"不利(ふり)는 불리, 有利(ゆうり)는 유리입니다."}]},"321":{"day":321,"ep":"58","epTitle":"東京第1結界⑤","epTitleKo":"도쿄 제1결계 5","title":"〜に沿って — ~에 따라서, ~을 따라","watch":"58화 중반 · 레지 일행이 계획대로 후시구로를 몰아붙이는 장면","scene":"레지 무리는 미리 짠 작전에 따라 움직이며 후시구로를 압박한다. 후시구로는 결계의 규칙과 지형을 머릿속으로 계산하며 반격할 길을 찾는다. 싸움은 머리싸움의 양상을 띠기 시작한다.","lines":[{"who":"레지","ja":"作戦に沿って動け。狙いは伏黒一人だ。","kana":"さくせんに そって うごけ。ねらいは ふしぐろ ひとり だ。","ko":"작전에 따라 움직여. 목표는 후시구로 하나다."},{"who":"후시구로","ja":"この道路に沿って進めば、奴らを引き離せる。","kana":"この どうろに そって すすめば、やつらを ひきはなせる。","ko":"이 도로를 따라 가면 놈들을 떼어 놓을 수 있다."},{"who":"후시구로","ja":"結界の規則を、もう一度頭の中で整理しよう。","kana":"けっかいの きそくを、もう いちど あたまの なかで せいり しよう。","ko":"결계의 규칙을 한 번 더 머릿속으로 정리하자."}],"words":[{"w":"戦略","r":"せんりゃく","ko":"전략"},{"w":"指針","r":"ししん","ko":"지침"},{"w":"道路","r":"どうろ","ko":"도로"},{"w":"準拠","r":"じゅんきょ","ko":"준거, 기준에 따름"},{"w":"包囲","r":"ほうい","ko":"포위"},{"w":"陣形","r":"じんけい","ko":"진형"},{"w":"軌道","r":"きどう","ko":"궤도"},{"w":"沿線","r":"えんせん","ko":"(철도·도로) 연선, 길가"}],"grammar":{"point":"〜に沿って","desc":"〜に沿って(にそって)는 두 가지 뜻이 있습니다. ① 길·강 같은 긴 것을 '따라서': 川に沿って歩く(강을 따라 걷다). ② 방침·계획·희망 등에 '맞춰서, 따라서': 計画に沿って進める(계획에 따라 진행하다). 명사를 꾸밀 때는 〜に沿った+명사(方針に沿った提案)로 씁니다. ②는 업무 메일·상담에서 매우 자주 씁니다.","ex":[{"ja":"お客様のご希望に沿って、プランを作成いたします。","kana":"おきゃくさまの ごきぼうに そって、ぷらんを さくせい いたします。","ko":"고객님의 희망에 맞춰 플랜을 작성하겠습니다."},{"ja":"マニュアルに沿って、手続きを進めてください。","kana":"まにゅあるに そって、てつづきを すすめて ください。","ko":"매뉴얼에 따라 절차를 진행해 주세요."}]},"convert":{"anime":"言われた通りにやっとけ。","real":"会社の方針に沿って対応いたします。","note":"やっとけ는 〜ておけ의 축약 명령형으로 거친 반말입니다. 고객 응대에서는 〜に沿って＋いたします로 '규정에 맞게 처리한다'는 신뢰감을 줍니다."},"mission":"고객이 '제 요청대로 해 주실 수 있나요?'라고 묻습니다. 〜に沿って를 써서 안심시키는 대답을 해 보세요.","missionEx":{"ja":"はい、ご要望に沿って準備を進めております。","kana":"はい、ごようぼうに そって じゅんびを すすめて おります。","ko":"네, 요청하신 대로 준비를 진행하고 있습니다."},"quiz":[{"q":"「川に沿って歩く」의 뜻은?","choices":["강을 건너 걷다","강을 따라 걷다","강을 향해 걷다"],"a":1,"why":"〜に沿って는 길·강 같은 것을 '따라서'라는 뜻입니다."},{"q":"'방침에 따른 제안'을 일본어로?","choices":["方針に沿って提案","方針で沿った提案","方針に沿った提案"],"a":2,"why":"명사를 꾸밀 때는 〜に沿った＋명사입니다."},{"q":"「準拠」의 뜻은?","choices":["준거, 기준에 따름","지시","계획"],"a":0,"why":"準拠(じゅんきょ)는 기준에 따르는 것. 法律に準拠する = 법률에 준거하다."}]},"323":{"day":323,"ep":"58","epTitle":"東京第1結界⑤","epTitleKo":"도쿄 제1결계 5","title":"〜につき — ~당, ~이므로 (공지·안내)","watch":"58화 중반 · 후시구로가 레지의 술식 원리를 꿰뚫어 보는 장면","scene":"후시구로는 싸우면서 레지의 술식이 영수증 한 장마다 물건 하나를 불러내는 방식이라는 것을 알아챈다. 사멸회유의 점수 규칙도 다시 떠올리며, 이 게임이 얼마나 비정상적인지 곱씹는다. 부상을 입은 상태라 오래 끌 수는 없다.","lines":[{"who":"후시구로","ja":"領収書一枚につき、一つ物を呼び出せるのか。","kana":"りょうしゅうしょ いちまいに つき、ひとつ ものを よびだせるのか。","ko":"영수증 한 장당 물건 하나를 불러낼 수 있는 건가."},{"who":"레지","ja":"泳者一人につき五点。単純なルールだろ？","kana":"えいしゃ ひとりに つき ごてん。たんじゅんな るーる だろ？","ko":"참가자 한 명당 5점. 단순한 규칙이지?"},{"who":"후시구로","ja":"この怪我じゃ、準備に時間はかけられない。","kana":"この けが じゃ、じゅんびに じかんは かけられない。","ko":"이 부상으로는 준비에 시간을 들일 수 없다."}],"words":[{"w":"禁止","r":"きんし","ko":"금지"},{"w":"工事","r":"こうじ","ko":"공사"},{"w":"断水","r":"だんすい","ko":"단수"},{"w":"割増","r":"わりまし","ko":"할증"},{"w":"改装","r":"かいそう","ko":"개장, 리모델링"},{"w":"営業","r":"えいぎょう","ko":"영업"},{"w":"休業","r":"きゅうぎょう","ko":"휴업"},{"w":"支払う","r":"しはらう","ko":"지불하다"}],"grammar":{"point":"〜につき","desc":"〜につき는 딱딱한 문어체로 두 가지 뜻이 있습니다. ① '~당, ~마다': 一人につき千円(1인당 천 엔). ② '~이므로'(이유): 工事中につき通行止め(공사 중이므로 통행금지). ②는 주로 공지문·안내문·게시물에 쓰이고 명사에 바로 붙습니다. 일상 대화에서는 ①은 〜あたり, ②는 〜ので로 말하는 경우가 많습니다.","ex":[{"ja":"本日は定休日につき、休業いたします。","kana":"ほんじつは ていきゅうびに つき、きゅうぎょう いたします。","ko":"오늘은 정기 휴일이므로 휴업합니다."},{"ja":"参加費は一人につき二千円です。","kana":"さんかひは ひとりに つき にせんえん です。","ko":"참가비는 1인당 2천 엔입니다."}]},"convert":{"anime":"工事中だから入んなよ。","real":"工事中につき、立ち入りはご遠慮ください。","note":"入んなよ는 入るな(들어가지 마)의 거친 축약입니다. 안내문이나 공식 공지에서는 〜につき와 ご遠慮ください로 정중하게 금지를 알립니다."},"mission":"세미나 안내문을 만들고 있습니다. 〜につき를 써서 '자료는 1인당 1부'라는 안내 문장을 만들어 보세요.","missionEx":{"ja":"資料はお一人様につき一部ずつお配りします。","kana":"しりょうは おひとりさまに つき いちぶ ずつ おくばり します。","ko":"자료는 1인당 1부씩 나눠 드립니다."},"quiz":[{"q":"「工事中につき」의 뜻은?","choices":["공사 중이므로","공사 중에도","공사 중이라도"],"a":0,"why":"명사＋につき는 공지문에서 '~이므로'라는 이유를 나타냅니다."},{"q":"'1인당 천 엔'을 일본어로?","choices":["一人まで千円","一人など千円","一人につき千円"],"a":2,"why":"'~당'은 〜につき로 나타냅니다."},{"q":"「断水」의 읽기는?","choices":["だんすい","たんすい","だんずい"],"a":0,"why":"断水(だんすい)는 수도가 끊기는 단수입니다. 工事につき断水 = 공사로 인해 단수."}]},"324":{"day":324,"ep":"58","epTitle":"東京第1結界⑤","epTitleKo":"도쿄 제1결계 5","title":"〜をめぐって — ~을 둘러싸고","watch":"58화 후반부 · 싸움의 끝에 '천사'라 불리는 인물이 등장하는 장면","scene":"점수와 규칙 추가를 둘러싸고 참가자들끼리의 다툼은 점점 격해진다. 후시구로는 사투 끝에 레지와의 싸움에 결판을 짓는다. 지친 그의 앞에 '천사'라 불리는 소녀가 나타나며 새로운 국면이 열린다.","lines":[{"who":"후시구로","ja":"点をめぐって、泳者同士が争っているのか。","kana":"てんを めぐって、えいしゃ どうしが あらそって いるのか。","ko":"점수를 둘러싸고 참가자끼리 싸우고 있는 건가."},{"who":"레지","ja":"ルールの追加をめぐって、みんな必死なんだよ。","kana":"るーるの ついかを めぐって、みんな ひっし なんだよ。","ko":"규칙 추가를 둘러싸고 다들 필사적이라고."},{"who":"후시구로","ja":"情報をめぐる交渉なら、後で聞いてやる。","kana":"じょうほうを めぐる こうしょう なら、あとで きいて やる。","ko":"정보를 둘러싼 협상이라면 나중에 들어 주지."}],"words":[{"w":"争う","r":"あらそう","ko":"다투다, 겨루다"},{"w":"追加","r":"ついか","ko":"추가"},{"w":"対立","r":"たいりつ","ko":"대립"},{"w":"紛争","r":"ふんそう","ko":"분쟁"},{"w":"主張","r":"しゅちょう","ko":"주장"},{"w":"利害","r":"りがい","ko":"이해(득실)"},{"w":"いがみ合う","r":"いがみあう","ko":"서로 으르렁대다"},{"w":"天使","r":"てんし","ko":"천사"}],"grammar":{"point":"〜をめぐって","desc":"〜をめぐって는 '~을 둘러싸고'라는 뜻으로, 어떤 문제나 대상을 중심으로 여러 사람이 다투거나 논의할 때 씁니다. 뒤에는 争う, 議論する, 意見が分かれる처럼 대립·논의를 나타내는 말이 옵니다. 명사를 꾸밀 때는 〜をめぐる＋명사(遺産をめぐる争い)로 씁니다. 뉴스·회의·상속 상담 등에서 자주 나옵니다.","ex":[{"ja":"相続をめぐって、家族の間でもめることがあります。","kana":"そうぞくを めぐって、かぞくの あいだで もめる ことが あります。","ko":"상속을 둘러싸고 가족 사이에 다툼이 생기는 경우가 있습니다."},{"ja":"新しい制度をめぐって、会議で意見が分かれました。","kana":"あたらしい せいどを めぐって、かいぎで いけんが わかれました。","ko":"새 제도를 둘러싸고 회의에서 의견이 갈렸습니다."}]},"convert":{"anime":"金のことで揉めてんじゃねえよ。","real":"費用をめぐって、ご家族で話し合いが必要かもしれません。","note":"揉めてんじゃねえよ는 〜ているんじゃない의 거친 축약 반말입니다. 고객에게는 〜をめぐって로 상황을 객관적으로 정리하고, かもしれません으로 부드럽게 제안합니다."},"mission":"고객이 '상속 준비가 왜 필요하죠?'라고 묻습니다. 〜をめぐって를 써서 미리 준비해야 하는 이유를 설명해 보세요.","missionEx":{"ja":"財産をめぐるトラブルを防ぐために、早めの準備が大切です。","kana":"ざいさんを めぐる とらぶるを ふせぐ ために、はやめの じゅんびが たいせつ です。","ko":"재산을 둘러싼 분쟁을 막기 위해 일찍 준비하는 것이 중요합니다."},"quiz":[{"q":"'유산을 둘러싼 다툼'을 일본어로?","choices":["遺産をめぐって争い","遺産をめぐる争い","遺産にめぐる争い"],"a":1,"why":"명사를 꾸밀 때는 〜をめぐる＋명사. 조사는 を입니다."},{"q":"「紛争」의 뜻은?","choices":["분쟁","교환","주장"],"a":0,"why":"紛争(ふんそう)는 분쟁. 주장은 主張(しゅちょう)입니다."},{"q":"〜をめぐって 뒤에 오기 자연스러운 말은?","choices":["ご飯を食べた","天気が良い","意見が分かれた"],"a":2,"why":"〜をめぐって 뒤에는 다툼·논의·대립을 나타내는 말이 옵니다."}]},"325":{"day":325,"ep":"59","epTitle":"仙台結界","epTitleKo":"센다이 결계","title":"〜ずつ — ~씩 (같은 양을 나누어)","watch":"59화 초반 · 옷코츠가 센다이 결계에 들어서는 장면","scene":"사멸회유가 시작되고, 옷코츠 유타는 홀로 센다이 결계에 들어간다. 그곳에서는 강한 술사와 주령 넷이 서로를 견제하며 점수를 조금씩 모으고 있었다. 옷코츠는 그 균형을 단번에 깨려고 한다.","lines":[{"who":"이시고리","ja":"今まで四人で少しずつ点を取り合ってきたんだ。","kana":"いままで よにんで すこしずつ てんを とりあって きたんだ。","ko":"지금까지 넷이서 조금씩 점수를 뺏고 뺏기며 왔지."},{"who":"옷코츠","ja":"一人ずつ相手をしている時間はありません。","kana":"ひとりずつ あいてを している じかんは ありません。","ko":"한 명씩 상대하고 있을 시간은 없어요."},{"who":"옷코츠","ja":"リカちゃん、少しずつでいいから力を貸して。","kana":"りかちゃん、すこしずつで いいから ちからを かして。","ko":"리카, 조금씩이라도 좋으니까 힘을 빌려줘."}],"words":[{"w":"こつこつ","r":"こつこつ","ko":"꾸준히, 차근차근"},{"w":"ちびちび","r":"ちびちび","ko":"찔끔찔끔"},{"w":"半分","r":"はんぶん","ko":"반, 절반"},{"w":"端数","r":"はすう","ko":"우수리, 끝수"},{"w":"上乗せ","r":"うわのせ","ko":"덧붙임, 추가"},{"w":"毎月","r":"まいつき","ko":"매달"},{"w":"着実","r":"ちゃくじつ","ko":"착실함"},{"w":"雀の涙","r":"すずめのなみだ","ko":"쥐꼬리만큼, 아주 적음"}],"grammar":{"point":"〜ずつ","desc":"「ずつ」는 수량 표현 뒤에 붙어 '~씩'이라는 뜻이 된다. 한국어 '한 명씩, 조금씩, 만 원씩'과 거의 똑같이 쓴다.\n一人ずつ(한 명씩), 少しずつ(조금씩), 一枚ずつ(한 장씩), 三万円ずつ(3만 엔씩)처럼 쓴다.\n같은 양을 나누거나 반복할 때 쓰므로 적립·분할 납입 설명에 아주 자주 나온다.\n조사 「を」 등은 ずつ 뒤에 오지만 생략되는 경우가 많다.","ex":[{"ja":"毎月三万円ずつ貯金しています。","kana":"まいつき さんまんえん ずつ ちょきん して います。","ko":"매달 3만 엔씩 저금하고 있습니다."},{"ja":"書類を一枚ずつ確認してください。","kana":"しょるいを いちまいずつ かくにん して ください。","ko":"서류를 한 장씩 확인해 주세요."}]},"convert":{"anime":"一人ずつ順番に来いよ。","real":"お一人ずつ順番にお入りください。","note":"「来いよ」는 싸움을 거는 거친 명령형이다. 상담 창구나 세미나 안내에서는 「お一人ずつ」「お入りください」처럼 존경 표현으로 바꾼다."},"mission":"고객에게 매달 일정 금액씩 적립하는 방법을 제안해 보세요. 금액을 바꿔 가며 말해 보면 좋습니다.","missionEx":{"ja":"毎月五万円ずつ積み立てるのはいかがでしょうか。","kana":"まいつき ごまんえん ずつ つみたてるのは いかが でしょうか。","ko":"매달 5만 엔씩 적립하시는 건 어떠세요?"},"quiz":[{"q":"「한 명씩 들어와 주세요」에 맞는 것은?","choices":["一人ずつ入ってください。","一人まで入ってください。","一人だけずつ入ってください。"],"a":0,"why":"'~씩'은 수량 뒤에 「ずつ」를 붙인다."},{"q":"「こつこつ」의 뜻은?","choices":["갑자기","꾸준히, 차근차근","허둥지둥"],"a":1,"why":"こつこつ는 조금씩 꾸준히 해 나가는 모양입니다. こつこつ貯める = 꾸준히 모으다."},{"q":"「少しずつ」의 뜻은?","choices":["조금밖에","조금씩","조금 전에"],"a":1,"why":"少し(조금) + ずつ(씩) = 조금씩."}]},"326":{"day":326,"ep":"59","epTitle":"仙台結界","epTitleKo":"센다이 결계","title":"〜とは限らない — 꼭 ~인 것은 아니다","watch":"59화 중반 · 옷코츠가 이시고리·우로와 맞붙는 장면","scene":"옷코츠의 등장으로 센다이 결계의 균형이 무너지고, 고대의 술사 이시고리 류와 우로 타카코가 옷코츠를 노린다. 엄청난 출력과 하늘을 다루는 술식 앞에서도 옷코츠는 침착하게 상황을 읽는다.","lines":[{"who":"이시고리","ja":"特級だからって、俺より強いとは限らないだろ？","kana":"とっきゅう だからって、おれより つよいとは かぎらない だろ？","ko":"특급이라고 해서 나보다 강하다고는 할 수 없잖아?"},{"who":"옷코츠","ja":"そうですね。でも、僕が負けるとも限りませんよ。","kana":"そう ですね。でも、ぼくが まけるとも かぎりませんよ。","ko":"그렇죠. 하지만 제가 진다고도 할 수 없어요."},{"who":"우로","ja":"空の上なら安全だと思った？そうとは限らないわ。","kana":"そらの うえなら あんぜんだと おもった？ そうとは かぎらないわ。","ko":"하늘 위라면 안전하다고 생각했어? 꼭 그렇지는 않아."}],"words":[{"w":"目減り","r":"めべり","ko":"(가치가) 줄어듦"},{"w":"元本割れ","r":"がんぽんわれ","ko":"원금 손실"},{"w":"確か","r":"たしか","ko":"확실함, 분명"},{"w":"利回り","r":"りまわり","ko":"수익률"},{"w":"確実","r":"かくじつ","ko":"확실"},{"w":"分散","r":"ぶんさん","ko":"분산"},{"w":"下落","r":"げらく","ko":"하락"},{"w":"見込み","r":"みこみ","ko":"전망, 가능성"}],"grammar":{"point":"〜とは限らない","desc":"「〜とは限らない」는 '꼭 ~인 것은 아니다, 반드시 ~라고는 할 수 없다'라는 뜻이다. 일반적인 생각에 예외가 있음을 부드럽게 말할 때 쓴다.\n보통형(명사·な형용사는 だ 생략 가능)에 붙인다: 高い保険がいいとは限らない.\n「必ず」「いつも」「誰でも」와 함께 쓰이는 경우가 많다.\n정중하게는 「〜とは限りません」. 고객의 오해를 정면으로 부정하지 않고 바로잡을 때 아주 유용하다.","ex":[{"ja":"値段が高い保険が、いい保険とは限りません。","kana":"ねだんが たかい ほけんが、いい ほけん とは かぎりません。","ko":"가격이 비싼 보험이 좋은 보험이라고는 할 수 없습니다."},{"ja":"経験が長い人が、いつも正しいとは限りません。","kana":"けいけんが ながい ひとが、いつも ただしい とは かぎりません。","ko":"경력이 긴 사람이 항상 옳은 것은 아닙니다."}]},"convert":{"anime":"強えやつが勝つとは限らねえ。","real":"強い人が必ず勝つとは限りません。","note":"「強え」「限らねえ」는 거친 남성 반말 축약이다. 회의나 상담에서는 「強い人」「限りません」으로 또박또박 말한다."},"mission":"고객이 '수익률 높은 상품이 무조건 좋은 거죠?'라고 묻습니다. 〜とは限りません으로 부드럽게 바로잡고, 이유를 한 마디 덧붙여 보세요.","missionEx":{"ja":"利回りが高い商品が、いつも良いとは限りません。","kana":"りまわりが たかい しょうひんが、いつも よい とは かぎりません。","ko":"수익률이 높은 상품이 항상 좋은 것은 아닙니다."},"quiz":[{"q":"「簡単に見える仕事が、楽だとは限らない」의 뜻은?","choices":["쉬워 보이는 일은 절대 편하지 않다","쉬워 보이는 일이 꼭 편한 것은 아니다","쉬워 보이는 일은 편할 리가 없다"],"a":1,"why":"〜とは限らない는 전부 부정이 아니라 '꼭 그렇지는 않다'는 부분 부정."},{"q":"「目減り」의 읽는 법은?","choices":["めべり","もくげり","めへり"],"a":0,"why":"目減り(めべり)는 가치가 줄어드는 것. インフレで貯金が目減りする."},{"q":"빈칸: 高い店がおいしい（　）。","choices":["とは限ります","には限らない","とは限らない"],"a":2,"why":"보통형 + とは限らない. 조사는 「と」+「は」."}]},"327":{"day":327,"ep":"59","epTitle":"仙台結界","epTitleKo":"센다이 결계","title":"〜ないわけではない — ~하지 않는 것은 아니다","watch":"59화 후반 · 이시고리가 싸움을 즐기며 옷코츠를 몰아붙이는 장면","scene":"이시고리는 오랜만에 만난 강적과의 싸움을 진심으로 즐긴다. 옷코츠 역시 두려움이 전혀 없는 것은 아니지만, 동료들을 위해 이곳에서 시간을 낭비할 수 없다는 각오로 맞선다.","lines":[{"who":"옷코츠","ja":"怖くないわけじゃない。でも、やるしかないんだ。","kana":"こわく ない わけじゃ ない。でも、やるしか ないんだ。","ko":"무섭지 않은 건 아니야. 그래도 할 수밖에 없어."},{"who":"이시고리","ja":"お前だって、この戦いを楽しんでないわけじゃないだろ？","kana":"おまえ だって、この たたかいを たのしんで ない わけじゃ ない だろ？","ko":"너도 이 싸움을 즐기지 않는 건 아니잖아?"},{"who":"옷코츠","ja":"自信がないわけではありません。ただ、急いでいるんです。","kana":"じしんが ない わけでは ありません。ただ、いそいで いるんです。","ko":"자신이 없는 건 아니에요. 다만 서두르고 있을 뿐이에요."}],"words":[{"w":"躊躇","r":"ちゅうちょ","ko":"주저"},{"w":"ためらう","r":"ためらう","ko":"망설이다"},{"w":"びくびく","r":"びくびく","ko":"벌벌, 겁먹은 모양"},{"w":"ひやひや","r":"ひやひや","ko":"조마조마"},{"w":"未練","r":"みれん","ko":"미련"},{"w":"腰が引ける","r":"こしがひける","ko":"겁먹고 꽁무니를 빼다"},{"w":"怖気づく","r":"おじけづく","ko":"겁먹다, 주눅 들다"},{"w":"戦慄","r":"せんりつ","ko":"전율"}],"grammar":{"point":"〜ないわけではない","desc":"「〜ないわけではない」는 '~하지 않는 것은 아니다'라는 이중 부정이다. 완전히 긍정하지는 않고 '어느 정도는 그렇다'고 조심스럽게 인정할 때 쓴다.\n동사·い형용사의 ない형 + わけではない: 行かないわけではない, 怖くないわけではない.\n명사·な형용사는 「〜じゃないわけではない」보다 「嫌いなわけではない」처럼 긍정형 + わけではない로 '꼭 ~한 건 아니다'를 쓰는 경우가 많다.\n회화체는 「〜ないわけじゃない」, 정중하게는 「〜ないわけではありません」. 뒤에 「ただ」「でも」로 진짜 하고 싶은 말을 잇는 패턴이 자연스럽다.","ex":[{"ja":"そのご提案に興味がないわけではありません。","kana":"その ごていあんに きょうみが ない わけでは ありません。","ko":"그 제안에 관심이 없는 것은 아닙니다."},{"ja":"時間がないわけではないんですが、今週は少し難しいです。","kana":"じかんが ない わけでは ないんですが、こんしゅうは すこし むずかしい です。","ko":"시간이 없는 건 아니지만, 이번 주는 조금 어렵습니다."}]},"convert":{"anime":"別に怖くねえわけじゃねえよ。","real":"不安がないわけではありません。","note":"「〜ねえわけじゃねえ」는 거친 남성 말투다. 업무 자리에서는 「〜ないわけではありません」으로 말하고, 감정어도 「怖い」보다 「不安」처럼 차분한 단어를 고르면 어른스럽다."},"mission":"고객이 '보험을 해지할까 고민 중'이라고 합니다. 고객의 마음을 인정하면서도(〜ないわけではありません) 신중하게 생각하자고 권해 보세요.","missionEx":{"ja":"お気持ちが分からないわけではありません。ただ、解約は慎重に考えましょう。","kana":"おきもちが わからない わけでは ありません。ただ、かいやくは しんちょうに かんがえましょう。","ko":"고객님 마음을 모르는 건 아닙니다. 다만 해지는 신중하게 생각해 보시죠."},"quiz":[{"q":"「行きたくないわけではない」의 뜻은?","choices":["절대 가고 싶지 않다","가고 싶을 리가 없다","가고 싶지 않은 것은 아니다"],"a":2,"why":"이중 부정으로 '어느 정도는 가고 싶다'는 조심스러운 긍정."},{"q":"「腰が引ける」의 뜻은?","choices":["좋아하다","겁먹고 꽁무니를 빼다","불안하다"],"a":1,"why":"腰が引ける(こしがひける)는 겁이 나서 소극적이 되는 것입니다."},{"q":"정중한 말로 알맞은 것은?","choices":["自信がないわけではありません。","自信がないわけじゃねえ。","自信がないわけではないだろ。"],"a":0,"why":"업무에서는 「〜わけではありません」."}]},"328":{"day":328,"ep":"59","epTitle":"仙台結界","epTitleKo":"센다이 결계","title":"〜得る / 〜得ない — ~할 수 있다 / ~할 수 없다","watch":"59화 클라이맥스 · 옷코츠가 리카를 완전히 불러내 결계를 정리하는 장면","scene":"옷코츠는 짧은 시간 동안만 가능한 리카의 완전 현현으로 단숨에 전세를 뒤집는다. 상대들은 믿기 어려운 힘에 놀라고, 센다이 결계의 싸움은 옷코츠의 승리로 끝난다. 3기를 마무리하는 장면이다.","lines":[{"who":"옷코츠","ja":"五分あれば、この状況は十分に変わり得る。","kana":"ごふん あれば、この じょうきょうは じゅうぶんに かわりうる。","ko":"5분이면 이 상황은 충분히 바뀔 수 있어."},{"who":"우로","ja":"こんな力を一人で持つなんて、あり得ないわ…！","kana":"こんな ちからを ひとりで もつ なんて、ありえないわ…！","ko":"이런 힘을 혼자 갖고 있다니, 말도 안 돼…!"},{"who":"이시고리","ja":"負けたが、考え得る中で最高の戦いだったぜ。","kana":"まけたが、かんがえうる なかで さいこうの たたかい だったぜ。","ko":"졌지만 생각할 수 있는 최고의 싸움이었다."}],"words":[{"w":"形勢","r":"けいせい","ko":"형세"},{"w":"逆転","r":"ぎゃくてん","ko":"역전"},{"w":"圧倒","r":"あっとう","ko":"압도"},{"w":"瞬く間","r":"またたくま","ko":"눈 깜짝할 사이"},{"w":"想定","r":"そうてい","ko":"상정, 예상해 둠"},{"w":"解決","r":"かいけつ","ko":"해결"},{"w":"あり得る","r":"ありうる","ko":"있을 수 있다"},{"w":"一網打尽","r":"いちもうだじん","ko":"일망타진"}],"grammar":{"point":"〜得る / 〜得ない","desc":"「동사 ます형 + 得る」는 '~할 수 있다, ~할 가능성이 있다'라는 딱딱한 표현이다. 起こり得る(일어날 수 있다), 考え得る(생각할 수 있다)처럼 쓴다.\n긍정형 得る는 「うる」로 읽는 경우가 많고(「える」도 가능), 부정형 得ない는 반드시 「えない」로 읽는다.\n가장 자주 쓰는 것은 「あり得る(ありうる)」=있을 수 있다, 「あり得ない(ありえない)」=있을 수 없다, 말도 안 된다.\n능력보다는 '가능성'을 말할 때 쓰므로, 위험·리스크 설명 같은 업무 문장에 잘 어울린다.","ex":[{"ja":"この計画には、いくつかの問題が起こり得ます。","kana":"この けいかくには、いくつかの もんだいが おこりえます。","ko":"이 계획에는 몇 가지 문제가 일어날 수 있습니다."},{"ja":"担当者が書類を確認しないことは、あり得ません。","kana":"たんとうしゃが しょるいを かくにん しない ことは、ありえません。","ko":"담당자가 서류를 확인하지 않는 일은 있을 수 없습니다."}]},"convert":{"anime":"マジかよ、ありえねえ！","real":"それは考えにくいと思います。","note":"「ありえねえ」는 젊은 층의 거친 감탄이다. 고객이나 상사 앞에서는 「考えにくいと思います」「あり得ないことではないでしょうか」처럼 단정을 피해 부드럽게 말한다."},"mission":"고객이 '저는 건강해서 병에 걸릴 일은 없어요'라고 합니다. 〜得る를 써서 누구에게나 일어날 수 있다고 설명해 보세요.","missionEx":{"ja":"病気やけがは、誰にでも起こり得ることです。","kana":"びょうきや けがは、だれにでも おこりうる ことです。","ko":"병이나 부상은 누구에게나 일어날 수 있는 일입니다."},"quiz":[{"q":"「あり得ない」의 읽는 법은?","choices":["ありえない","ありうない","ありとくない"],"a":0,"why":"부정형 得ない는 항상 「えない」로 읽는다."},{"q":"「起こり得る」의 뜻은?","choices":["일어나야 한다","일어났을 것이다","일어날 수 있다"],"a":2,"why":"ます형(起こり) + 得る = ~할 수 있다(가능성)."},{"q":"「形勢」의 뜻은?","choices":["상황","형세","예상"],"a":1,"why":"形勢(けいせい)는 형세. 形勢逆転 = 형세 역전."}]}});
